(window.STORIES=window.STORIES||[]).push(...[{"n": 228, "l": "الجزء 202 | احداث السنه التاسعه من الهجرة | اعتزال رسول الله لنسائه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_واثنين\n#أحداث_السنة_التاسعة_من_الهجرة\n#اعتزال_رسول_الله_لنسائه\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما كان رجع من تبوك وأمر بحرق مسجد اتبنى في المدينة،\nإيه قصة حرق وهدم المسجد ده\nهنرجع بالزمن شوية كده ونفتكر قصة أبو عامر الراهب أو أبو عامر الفاسق زي ما كان سمّاه رسول الله ﷺ،\nاحنا كنا اتكلمنا عنه في الجزء الخمسين لو تفتكروا وقلنا إنه \nكان بيقول عن نفسه إنه راهب وعنده علم وإنه كان على الحنيفية دين إبراهيم عليه السلام،\nولما رسول الله ﷺ جاء للمدينة قعد اتكلم معاه وقال عن رسول الله ﷺ إنه حرّف في دين إبرهيم عليه السلام وإن رسول الله ﷺ كاذب،\nوبعدين أبو عامر ده قال لرسول الله ﷺ يارب الكذاب يموت طريد غريب وحيد، فرسول الله ﷺ قال يارب فعلا الكاذب ربنا يعمل فيه كده،\nوبعدها خرج أبو عامر من المدينة وراح قعد في مكة وفي غزوة أحد كان هو إللي حفر الحُفر إللي وقع رسول الله ﷺ في واحدة منها،\nوقلنا إنه قعد في مكة لحد فتح مكة وفي الآخر راح قعد في الشام،\nلما راح الشام قابل هرقل واستنصره على رسول الله ﷺ، يعني قعد يطلب من هرقل إنه يجهز جيش عشان يقاتل رسول الله ﷺ في المدينة،\nفكان هرقل بيوعده ويُمَنّيه، يعني يقوله طبعا طبعا هنروح نقاتل محمد ﷺ ونقضي عليه بس هنستنى الوقت المناسب،\nيعني من الآخر كده كان بياخده على أد عقله\nفِضل أبو عامر الراهب موجود في الشام وفي نفس الوقت بيراسل المنافقين إللي في المدينة ويقولهم إنه هييجي ومعاه جيش يقاتل به رسول الله ﷺ ويغلبه وينتصر عليه ويتخلص منه وترجع لهم المدينة بقى زي زمان،\nفأمرهم إنهم يعملوا زي مقر كده ييتجمعوا فيه ويرسل لهم عليه الرسايل بتاعته وكمان لما يرجع يكون المقر ده هو المكان إللي يتحرك منه ويدير منه المدينة،\nفبدأوا يبنوا مسجد بجوار مسجد قباء، \nبنوا المسجد ده وخلصوا بناؤه في وقت خروج رسول الله ﷺ لتبوك،\nفجاءوا لرسول الله ﷺ يطلبوا منه إنه يصلي في المسجد إللي بنوه ده،\nيعني عشان ياخدوا شرعية قصاد الناس احنا تمام أوي وإللي بنعمله صح حتى إن رسول الله ﷺ جاء صلى في المسجد بتاعنا\nوقالوا لرسول الله ﷺ إنهم بنوه عشان الضعفاء وإللي ملوش مأوى يقعد فيه، وطبعا كده محدش هيقدر يعترض على أي تجمعات تحصل داخل المسجد،\nيعني همّ حبكوا خطة مُحكمَة عشان ينفذوا إللي همّ عايزينه\nسبحان الله بقى يمكرون ويمكر الله والله خير الماكرين،\nربنا عصم رسول الله ﷺ من إنه يصلي فيه،\nلسه لحد دلوقتي رسول الله ﷺ ميعرفش حاجة عن المسجد ده والوحي مجاش بأي حاجة،\nرسول الله ﷺ ساعتها رد عليهم بإنه دلوقتي مشغول بالسفر والخروج لتبوك، وفعلا مفيش مجال إنه يترك الجيش إللي خارج ده ويروح يصلي في مسجد بعيد عن مكان الجيش وينشغل بحاجة تانية،\nفقال لهم إنه لما يرجع هيبقى يصلي فيه،\nبعد غزوة تبوك ما خلصت ورسول الله ﷺ راجع للمدينة قبل ما يوصل للمدينة بساعة نزل الوحي يخبر رسول الله ﷺ بحقيقة مسجد الضّرار،\nقال الله عز وجل في سورة التوبة:\n\"وَالَّذِينَ اتَّخَذُوا مَسْجِدًا ضِرَارًا وَكُفْرًا وَتَفْرِيقًا بَيْنَ الْمُؤْمِنِينَ وَإِرْصَادًا لِمَنْ حَارَبَ اللَّهَ وَرَسُولَهُ مِنْ قَبْلُ وَلَيَحْلِفُنَّ إِنْ أَرَدْنَا إِلَّا الْحُسْنَى وَاللَّهُ يَشْهَدُ إِنَّهُمْ لَكَاذِبُونَ ۩\n لَا تَقُمْ فِيهِ أَبَدًا لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ فِيهِ رِجَالٌ يُحِبُّونَ أَنْ يَتَطَهَّرُوا وَاللَّهُ يُحِبُّ الْمُطَّهِّرِينَ\"\nربنا أخبر رسول الله ﷺ بالمنافقين إللي بنوا مسجد الضرار ده عشان يفرقوا بين المسلمين؛ \nلأن المسلمين كانوا كلهم بيصلوا في مسجد قِباء فلما يبنوا مسجد تاني جنب مسجد قباء كده هينقسم المسلمون، فهيبقى في فريق هيصلي في مسجد قباء وفريق هيصلي في المسجد إللي المنافقين بنوه،\nوكمان يكون مكان ينتظروا فيه أبو عامر الراهب، \nولو رسول الله ﷺ سأل المنافقين عن المسجد هيقولوا له والله احنا بنيناه عشان احنا عايزين نوسع على المسلمين ومش عايزين إلا الخير،\nفربنا بعد ما وضّح لرسول الله ﷺ إن المسجد إللي اتبنى ده مسجد ضِرار أمره إنه لا يصلي فيه أبدا ولكنه قاله إنه يصلي في مسجد قباء إللي اتأسس من البداية على التقوى أو مسجد رسول الله ﷺ على اختلاف بين العلماء أنهي مسجد مقصود في الآية :\n《لَمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَى مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَنْ تَقُومَ فِيهِ》\nبس عامة يعني همّ الاتنين كان تأسيسهم على التقوى وعلى طاعة الله ورسوله من أول يوم\nبعد ما رسول الله ﷺ عرف قصة مسجد الضرار أمر اتنين من الصحابة إنهم يسبقوه للمدينة ويروحوا لمسجد الضرار ده ويحرقوه ويهدموه،\nففعلا انطلق الصحابيان للمسجد وحرقوه وهدموه والناس إللي كانوا متجمعين فيه هربوا،\nوطبعا اتعرفت قصة مسجد الضرار وانتشرت بين المسلمين\nوبكده انتهت غزوة تبوك مع أهم الأحداث إللي حصلت فيها\nهنقف هنا بقى ونرجع للأحداث الداخلية إللي حصلت قبل خروج رسول الله ﷺ لغزوة تبوك،\nقلنا في الجزء المائة وتسعين إن خلال الفترة ما بين معرفة رسول الله ﷺ لتجمّع الرومان وقبل ما ياخد القرار هيعمل إيه مع الرومان حصلت حادثتين:\n◇الأولى هي: \nإِيلَاء رسول الله ﷺ من زوجاته.\n◇والثانية هي:\n تخيِير زوجات رسول الله ﷺ بين البقاء معه أو إنه يطلقهن.\nوقلنا هنتكلم عنهم بعد ما نخلص غزوة تبوك.\nهناخد الحادثة الأولى وهي:\n◇إِيلَاء رسول الله ﷺ من زوجاته أو اعتزاله لهن ﷺ.\nاحنا عارفين إن رسول الله ﷺ متزوج دلوقتي من تسع زوجات هن:\n♡سودة بنت زمعة\n♡عائشة بنت أبي بكر\n♡حفصة بنت عمر\n♡جُوَيرية بنت الحارث\n♡أم سلمة هند بنت أبي أمية\n♡زينب بنت جحش\n♡أم حبيبة رملة بنت أبي سفيان\n♡صفية بنت حيي بن أخطب\n♡ميمونة بنت الحارث\nحصلت أحداث من زوجات رسول الله ﷺ خلته يغضب ويتضايق منهن وحلف إنه هيعتزلهن ولن يدخل عليهم شهر من كتر ما كان من متضايق من إللي حصل.\nإيه إللي حصل\nعبد الله بن عباس رضي الله عنه بيحكي وبيقول إنهم في يوم من الأيام صحيوا لقوا نساء النبي ﷺ بيبكوا وكل واحدة عندها أهلها والمسجد مليان بالناس وانتشر بين الناس إن رسول الله ﷺ طلّق زوجاته\nوسط الأحداث دي عبد الله بن عباس لقى عمر بن الخطاب جاي بسرعة وبيستأذن للدخول على رسول الله ﷺ.\n☆إيه حكاية عمر وإيه إللي جابه في الوقت ده بالذات\nالموضوع ده له قصة\nعمر بن الخطاب رضي الله عنه بيحكي وبيقول إنه في يوم من الأيام كان بيفكر في موضوع وبيدور على حل،\nفزوجته بتقوله لو فعلت كذا وكذا،\nيعني بتعرض عليه رأيها، زي مثلا لما يبقى زوج عنده مشكلة وزوجته تقوله طيب ما تعمل كذا وكذا،\nفنفس الموقف حصل مع عمر بن الخطاب رضي الله عنه،\nفعمر قالها:\nمَا لَكَ وَلِمَا هَا هُنَا وَفِيمَ تَكَلُّفُكِ فِي أَمْرٍ أُرِيدُهُ\nيعني باللغة الدارجة بتاعتنا بيقولها انتِ مالك انتِ ومال إللي أنا بفكر فيه، وتدخلي نفسك فيه ليه أصلا\nوفي رواية تانية إن عمر رضي الله عنه صاح بامرإته، يعني زعّق لزوجته وعلّى صوته عليها،\nفردت عليه وراجعته في الكلام، فأنكر عليها عمر رضي الله عنه إزاي ترد عليه وتراجعه في كلامه،\nفقالت له:\nعَجَبًا لَكَ يَا ابْنَ الْخَطَّابِ مَا تُرِيدُ أَنْ تُرَاجَعَ أَنْتَ وَإِنَّ ابْنَتَكَ لَتُرَاجِعُ رَسُولَ الله ﷺ حَتَّىٰ يَظَلَّ يَوْمَهُ غَضْبَانَ\nوفي رواية تانية قالت:\nولِمَ تُنْكِرُ أنْ أُرَاجِعَكَ، فَوَاللَّهِ إنَّ أزْوَاجَ النبيِّ ﷺ ليُرَاجِعْنَهُ، وإنَّ إحْدَاهُنَّ لَتَهْجُرُهُ اليومَ حتَّى اللَّيْلِ\nيعني هي بتقول له انت زعلان ليه يعني عشان برد عليك وبعترض على كلامك ورسول الله ﷺ وهو رسول الله زوجاته بيراجعوه وبيردوا عليه ومش بس كده، ده كمان ممكن الواحدة تهجره طول اليوم ومتتكلمش معاه وتسيبه غضبان،\n☆ليه عمر رضي الله عنه غضب واعترض إن زوجته ترد عليه وتراجعه\nإللي يجاوبنا على السؤال ده عمر بن الخطاب نفسه\nعمر بيقول:\n\" كُنَّا مَعْشَرَ قُرَيْشٍ نَغْلِبُ النِّسَاءَ، فَلَمَّا قَدِمْنَا علَى الأنْصَارِ إذَا قَوْمٌ تَغْلِبُهُمْ نِسَاؤُهُمْ، فَطَفِقَ نِسَاؤُنَا يَأْخُذْنَ مِن أدَبِ نِسَاءِ الأنْصَارِ\"\nيعني رجال قريش كانوا بيفرضوا رأيهم وكلمتهم هي إللي تمشي والمرأة مكنش لها أي رأي نهائي ولا تنطق بكلمة ولا لها لازمة عندهم ومكنش الواحد فيهم يكلم زوجته إلا لو كان محتاج حاجة منها،\nغير كده ولا كانوا بيهتموا بأمر النساء ولا بيسمحوا لهم إنهم يتدخلوا في شؤونهم،\nلكن بقى لما حصلت الهجرة وانتقل المهاجرون للمدينة لقوا إن نساء الأنصار لهم نفوذ وبيدخلوا في أمور أزواجهم وبيقولوا رأيهم وكلامهم هو إللي بيمشي،\nيعني المرأة في المدينة قبل الإسلام كانت واخدة وضعها \nفلما حصل التداخل بين نساء المهاجرين ونساء الأنصار بدأ نساء المهاجرين ياخدوا من طباع نساء الأنصار،\nوكمان نزلت الآيات بالإحسان للمرأة ومعاشرتها بالمعروف،\nوالصحابة شافوا معاملة رسول الله ﷺ لزوجاته فوضع المرأة في الإسلام اتغير تماما،\nفعمر لسه في طبعه ومش متقبل إن زوجته تراجعه وترد عليه، فهي قالت إن ده عادي ورسول الله ﷺ نفسه زوجاته بيعملوا معاه كده فانت مش أحسن منه يعني.\n☆وفي هنا ملحوظة مهمة\nلو كان الصح إن المرأة متتكلمش ومتقولش رأيها وإنها تتعامل كأن ملهاش وجود مكنش رسول الله ﷺ سمح لنساء المهاجرين إنهم يتعلموا من طباع نساء الأنصار،\nبالعكس كمان ده كان ساعتها رسول الله ﷺ هيأمر نساء الأنصار إنهم يغيروا من طباعهم دي،\nلكن حصل العكس وهو إن الإسلام سمح للمرأة إنها تقول رأيها وتتدخل في شؤون زوجها وكمان ممكن زوجها ياخد برأيها زي ما رسول الله ﷺ أخذ برأي أم سلمة رضي الله عنها في صلح الحديبية،\nوطبعا يا جماعة كل ده بما لا يُخالف شرع ربنا أو إن المراة تفرض رأيها في أي شيء مُحرّم، هنا لا يُعتد برأيها أصلا\nيعني باختصار:\nالمرأة تُعطى فسحة بما لا يُخالف الشرع،\nويكون لها شأن يناسبها، ومكانة تتلاءم مع خلقتها إللي ربنا خلقها عليها زي مسألة استشارة الرجل لزوجته زي ما قلنا، أو السماح لها بإبداء رأيها، وإشراكها في اتخاذا القرار\nوكل ده من إكرام الزوج لزوجته،\nوللأسف في بعض الرجال بيرفضوا أخذ رأي الزوجة في أي شيء، أو ياخد رأيها ويعمل عكسه\nويقولوا حديث منسوب لرسول الله ﷺ بيقول فيه:\n\"شاوروهن وخالفوهن فإن في خلافهن البركة\" \nوطبعا الحديث لا يصح عن رسول الله ﷺ وملوش أصل\nلأ وكمان بيخالف فعل رسول الله ﷺ لما استشار أم سلمة وعمل بمشورتها زي ما شرحنا بالتفصيل قبل كده\nالمهم،\nهنرجع لعمر بن الخطاب لما عرف إن أزواج رسول الله ﷺ بيراجعوه وممكن يسيبوه غضبان، قال عمر لزوجته وهو مفزوع من الكلام إللي سمعه:\nقدْ خَابَ مَن فَعَلَ ذَلِكِ منهنَّ\nفقام نازل بسرعة وراح لحفصة ودخل عليها وسألها:\nأتُغاضِبُ إحْداكُنَّ رَسولَ الله ﷺاليَومَ حتَّى الَّليلِ؟\nفقالت له: نَعمْ. \nفرد عليها عمر وقال لها:\n\"خَابَتْ وخَسِرَتْ!\n أفَتَأْمَنُ أنْ يَغْضَبَ اللَّهُ لِغَضَبِ رَسولِهِ ﷺ، فَتَهْلِكِينَ لا تَسْتَكْثِرِي علَى رَسولِ اللَّهِ ﷺ، ولَا تُرَاجِعِيهِ في شيءٍ، ولَا تَهْجُرِيهِ، واسْأَلِينِي ما بَدَا لَكِ،\nولَا يَغُرَّنَّكِ أنْ كَانَتْ جَارَتُكِ هي أوْضَأَ مِنْكِ، وأَحَبَّ إلى رَسولِ اللَّهِ ﷺ\"\nيعني عمر بيقولها إن إللي تُغضب رسول الله ﷺ وتهجره تأمن منين إن ربنا لا يغضب عليها لغضب رسوله وتهلك في الآخر؟\nوبدأ عمر ينصحها إنها لا تُكثر من طلباتها من رسول الله ﷺ ولا تراجعه في شيء وتسمع كلامه ولا تهجره،\nولو هي محتاجة أي حاجة تطلبها منه هو مش من رسول الله ﷺ،\nوقالها ميغركيش إن رسول الله ﷺ بيدلل زوجته الثانية فتفكري نفسك زيها، هو هنا كان بيتكلم عن عائشة رضي الله عنها،\nفبيقولها إن مكانة عائشة عند رسول الله ﷺ غير مكانتك عنده، هو ممكن يتقبل منها إللي ميتقبلوش منك، فمتعمليش زيها،\nوهنا احنا شايفين أد إيه عمر رضي الله عنه كان حريص على استقرار بيت بنته وحريص إنها لا تُغضب زوجها\nطبعا الوضع استمر كما هو عليه\nعمر رضي الله عنه كان له صاحب من الأنصار، كانوا همّ الاتنين بيتناوبوا عند رسول الله ﷺ،\nيعني يوم عمر يجلس عند رسول الله ﷺ يتعلم منه، وصاحبه الأنصاري يشتغل في التجارة،\nوبعدين عمر يروح يعلم الأنصاري إللي اتعلمه من رسول الله ﷺ،\nواليوم التاني عمر يروح يمسك التجارة مكان الأنصاري والأنصاري يروح يتعلم من رسول الله ﷺ ولما يرجع يعلم عمر رضي الله عنه إللي اتعلمه من رسول الله ﷺ وهكذا،\nفي يوم بقى الأنصاري كان عليه الدور إنه يروح يتعلم من رسول الله ﷺ، فجاء لعمر وقعد يخبط على بابه بشدة،\nفعمر فتح الباب وهو مخضوض لقى صاحبه، فصحابه قال له:\nحَدَثَ أمرٌ عَظيمٌ\nفعمر سأله إيه إللي حصل، أجاءَتْ غَسَّانُ\nيعني الروم والغساسنة إللي كانوا بيجهزوا لغزو المدينة جاءوا؟! والكلام ده كان قبل غزوة تبوك زي ما قلنا،\nفالأنصاري قال لعمر:\nبَلْ أعظمُ مِنهُ وأطولُ، طَلَّقَ رسول الله ﷺ نِساءَهُ\n☆يعني همّ عندهم إن رسول الله ﷺ يزعل ويتكدر خاطره  أعظم عندهم من إن الغساسنة يغزون المدينة\nفعمر لما سمع الأنصاري قال كده، قال عمر:\nقَدْ خابَتْ حَفْصَةُ وخَسِرَتْ كُنْتُ أظُنُّ أنَّ هذا يُوشِكُ أنْ يَكونَ\nيعني بيقول أنا كنت عارف إن ده هيحصل، بسبب إللي كانوا بيعملوه من هجرهن لرسول الله ﷺ واعتراضهن عليه،\n☆طبعا رسول الله ﷺ لم يُطلق نساؤه لكن هي إشاعة انتشرت بين الناس، وكثير من العلماء قالوا إن إللي نشر الإشاعة دي هم المنافقون.\nالمهم،\nعمر رضي الله عنه توجه للمسجد وصلى الصبح مع رسول الله ﷺ وبعدها رسول الله ﷺ دخل غرفة بسلالم بيسموها مَشْرُبَة واعتزل فيها،\nوتوجه عمر لبنته حفصة ودخل عليها لقاها بتبكي فقال لها:\nما يُبْكِيكِ؟! أوَلَمْ أكُنْ حَذَّرْتُكِ؟ أُطَلَّقَكُنَّ رسول الله ﷺ ؟\nيعني بيقولها بتعيطي ليه هو أنا مش كنت حذرتك قبل كده،\nوسألها هل رسول الله ﷺ طلقهن فعلا زي ما سمع ولّا إيه إللي حصل،\nفقالت له حفصة: لا أدْري، هو ذَا في المَشْرُبَةِ\nعمر خرج  من عندها ودخل المسجد فلقى مجموعة من الصحابة، أقل من عشرة أشخاص قاعدين حول المنبر بيبكوا على إللي حصل وإزاي رسول الله ﷺ قاعد زعلان،\nوده من حبهم له ﷺ، مش مستحملين إن رسول الله ﷺ يبقى قاعد زعلان كده،\nفعمر قعد معاهم شوية وبعدين مقدرش يستحمل،\nهو آخر حاجة وصلت له إن رسول الله ﷺ طلق نساؤه،\nفمعنى إن رسول الله ﷺ يطلق نساؤه أو حتى يعتزلهم فده أكيد بسبب غضبه عليهن،\nفقام عمر وتوجه للغرفة إللي رسول الله ﷺ معتزل فيها،\nفسلم عمر على رسول الله ﷺ من خارج الغرفة عشان يدخل يعني فمحدش رد عليه،\nوفي رواية تانية إن عمر راح لغلام أسود اسمه رباح كان غلام لرسول الله ﷺ واقف على باب الغرفة، فقال له عمر:\nاستأذن لعمر!\nيعني قاله يدخل يستأذن رسول الله ﷺ إن عمر يدخل عشان عايز يكلمه،\nفدخل الغلام لرسول الله ﷺ ورجع لعمر وقاله إنه أخبر رسول الله ﷺ إنك موجود وعايز تقابله ورسول الله ﷺ مردش بحاجة،\nفعمر راح قعد و بعد شوية كده مقدرش يستحمل فرجع تاني للغلام وقال له: استأذن لعمر!\nيعني ادخل على رسول الله ﷺ وقول له إني عايز أقابله، فدخل الغلام وخرج وقال لعمر: ذكرتك له فلم يرد\nفراح عمر وقعد بعيد شوية وبرده مقدرش يستحمل فرجع للمرة الثالثة وقال للصحابي استأذن لعمر،\nفلم يؤذن له، ولما كان هيمشي خلاص نادى الغلام على عمر وقال له إن رسول الله ﷺ أذن له في الدخول،\nودخل عمر رضي الله عنه على رسول الله ﷺ،\nياترى إيه إللي حصل بين عمر وبين رسول الله ﷺ،\nوإيه إللي وصّل رسول الله ﷺ الرفيق الصبور واسع الصدر للمرحلة دي؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 229, "l": "الجزء 203 | احداث السنه التاسعه من الهجرة | تخيير زوجات رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثلاثة\n#أحداث_السنة_التاسعة_من_الهجرة\n#تخيِير_زوجات_رسول_الله\nوقفنا المرة إللي فاتت عند عمر رضي الله عنه لما دخل على رسول الله ﷺ في المَشْرُبَةِ، إللي هي الغرفة إللي بيطلعوا لها بسلالم دي وإللي كان رسول الله ﷺ معتزل فيها،\nلما دخل عمر رضي الله عنه لقى رسول الله ﷺ مُضْطَجِعٌ علَى رِمَالِ حَصِيرٍ ليسَ بيْنَهُ وبيْنَهُ فِرَاشٌ، قدْ أثَّرَ الرِّمَالُ بجَنْبِهِ مُتَّكِئٌ علَى وِسَادَةٍ مِن أدَمٍ حَشْوُهَا لِيفٌ،\nيعني عمر شاف رسول الله ﷺ نايم على جنبه على حصيرة مفيش بينه وبين الحصيرة أي فراش، وعلامات الحصيرة مأثرة في جنبه وساند إيده على مخدة من جلد حشوها من الداخل ليف،\nفسلم عمر على رسول الله ﷺ وقال له وهو لسه واقف:\nطَلَّقْتَ نِسَاءَكَ؟!\nيعني انت طلقت زوجاتك زي ما هو الناس بتقول،\nفرفع رسول الله ﷺ بصره لعمر وقال له: لَا!\nفهنا عمر قال وكأن كان في حِمل وانزاح من على قلبه:\nاللَّهُ أكْبَرُ.\nكبّر من الفرح إن رسول الله ﷺ لم يطلق نسائه، بس لسه حاسس إن الجو فيه توتر ورسول الله ﷺ لسه غضبان وواضح عليه علامات الزعل\nفبدأ عمر يلطّف الأمور مع رسول الله ﷺ، زي كده لما يبقى في حد عزيز علينا وشايفينه متضايق فبنحاول نضحكه ونقول أي حاجة تخفف عنه همه وضيقه،\nفده إللي عمر رضي الله عنه عمله،\nبدأ يحكي له الموقف إللي حصل بينه وبين زوجته قبل كده واحنا حكيناه المرة إللي فاتت،\nقال لرسول الله ﷺ:\nلو شفت يا رسول الله إللي حصل معايا، احنا معشر قريش بنغلب النساء وبنمشي كلامنا عليهم، فلما جينا هنا المدينة لقينا النساء هم إللي بيمشوا كلامهم، ونساءنا اتعلموا من نساؤهم لدرجة إن زوجتي نفسها لقيتها بتراجعني وبتدخل في شؤوني\nيعني عمر عايز يقول لرسول الله ﷺ:\nانت يا رسول الله أخذت بسيرة الأنصار وسمحت للنساء بالكلام وادتهم مساحة في الحرية فهجرنك ونشزن عليك، لكن لو كنت مشيت معاهم بطريقة القرشيين مكنش الحال وصل للي احنا فيه دلوقتي،\nفلما رسول الله ﷺ سمع كلام عمر تبسم ﷺ\nفعمر كمّل كلامه عشان يلطف الجو أكثر فحكى له إنه بعد الموقف إللي حصل بينه وبين زوجته راح بعدها لحفصة وقالها ميغركيش إن رسول الله ﷺ بيدلل عائشة فتفكري نفسك زيها،\nمكانتك عند رسول الله ﷺ غير مكانة عائشة عنده، هو ممكن يتقبل منها إللي ميتقبلوش منك، فمتعمليش زيها،\nفتبسم رسول الله ﷺ مرة تانية، وهنا عمر رضي الله عنه قعد بعد ما كان واقف طول الحوار ده كله،\nهو خلاص حقق إللي كان عايزه بإنه يضحّك رسول الله ﷺ ويخرجه من إحساس الضيق إللي كان فيه،\nلما عمر قعد بدأ ينظر للغرفة إللي رسول الله ﷺ قاعد فيها،\nالغرفة دي هي غرفة رئيس الدولة والقائد الأعلى للجيوش الإسلامية،\nفلقى إن الغرفة مفيهاش غير:\nثلاث قطع من الجلد غير مدبوغة، وفِراش من حصير، وقبضة من شعير،\nفهنا عمر تأثر إن رسول الله ﷺ على مكانته وعظمته مفيش في بيته غير الحاجات البسيطة دي وشاف الحصير أثّر في جنب رسول الله ﷺ فبكى عمر رضي الله عنه،\nفسأله رسول الله ﷺ:\n\"مَا يُبْكِيكَ يَا ابْنَ الْخَطَّابِ\"\nفقال له عمر:\n\"يَا نَبِيَّ الله وَمَا لِي لَا أَبْكِي وَهَذَا الْحَصِيرُ قَدْ أَثَّرَ فِي جَنْبِكَ وَهَذِهِ خِزَانَتُكَ لَا أَرَىٰ فِيهَا إِلَّا مَا أَرَىٰ وَذَاكَ قَيْصَرُ وَكِسْرَىٰ فِي الثِّمَارِ وَالْأَنْهَارِ وَأَنْتَ رَسُولُ الله وَصَفْوَتُهُ وَهَذِهِ خِزَانَتُكَ\"\nوفي رواية تانية قال له:\n\"ادْعُ اللَّهَ فَلْيُوَسِّعْ علَى أُمَّتِكَ، فإنَّ فَارِسَ والرُّومَ وُسِّعَ عليهم، وأُعْطُوا الدُّنْيَا وهُمْ لا يَعْبُدُونَ اللَّهَ\"\nيعني عمر بيقول إزاي يعني يا رسول الله لا أبكي وانت الحصير مأثر في جنبك ومعندكش خزين غير قبضة من شعير وقيصر وكسرى بيتنعموا في القصور والثمار والأنهار،\nوانت رسول الله وصفوته من خلقه عايش في فقر،\nفادعو الله يا رسول الله إنه يوسع على أمتك فهو وسّع على فارس والروم وعايشين متنعمين على الرغم من إنهم لا يعبدون الله.\nفهنا رسول الله ﷺ جلس بعد ما كان متكئ على جنبه وقال لعمر عشان يعلمه ويعلمنا قاعدة مهمة جدا\nقال رسول الله ﷺ:\n\"أَوَفِي شَكٍّ أنْتَ يا ابْنَ الخَطَّابِ؟!!\nيعني هل انت عندك شك في أن التوسّع في الآخرة خير من التوسع في الدنيا؟!\n\"أُولَئِكَ قَوْمٌ عُجِّلَتْ لهمْ طَيِّبَاتُهُمْ في الحَيَاةِ الدُّنْيَا\"\nيعني الناس دي ربنا عجّل لهم المتع بتاعتهم في الدنيا وملهمش حاجة في الآخرة،\n\"يَا ابْنَ الْخَطَّابِ أَلَا تَرْضَىٰ أَنْ تَكُونَ لَنَا الْآخِرَةُ وَلَهُمْ الدُّنْيَا\"\nيعني رسول الله ﷺ بيقوله انت متحبش إن يبقى همّ لهم الدنيا إللي مهما طال نعيمها فهي زائلة واحنا لنا الآخرة إللي فيها النعيم الأبدي\nفعمر قال لرسول الله ﷺ:\nيا رَسولَ اللَّهِ، اسْتَغْفِرْ لِي!\nيعني بيطلب من رسول الله ﷺ إنه يدعي له ربنا إنه يغفر له جرأته على إنه يقول الكلام ده لرسول الله ﷺ.\n☆القاعدة أو الدرس إللي احنا محتاجين نتعلمه هنا إن مش شرط أبدا إن الإنسان عشان مؤمن ربنا يفتح عليه من ألوان النعيم في الدنيا وميتعرضش لأي بلاء،\nولا هو شرط إن لو واحد كافر لازم يعيش في فقر وميشفش أي نعيم ويفضل طول عمره في ابتلاءات،\nمهما كان الكافر والظالم عايش في قمة النعيم في الدنيا فده نعيم هينتهي في يوم من الأيام والعبرة بالآخرة إللي نعيمها لا ينتهي أبدا،\nومش بس كده، ده حتى الناس إللي احنا شايفينهم عايشين مبسوطين ومُنعمين وهمّ من أهل النار الواحد فيهم لما يتغمس غمسة واحدة بس في النار هينسى كل نعيم شافه في حياته،\nرسول الله ﷺ بيقول:\nيُؤْتَى بأَنْعَمِ أهْلِ الدُّنْيا مِن أهْلِ النَّارِ يَومَ القِيامَةِ، فيُصْبَغُ في النَّارِ صَبْغَةً، ثُمَّ يُقالُ:\nيا ابْنَ آدَمَ هلْ رَأَيْتَ خَيْرًا قَطُّ؟ هلْ مَرَّ بكَ نَعِيمٌ قَطُّ؟\nفيَقولُ: لا، واللَّهِ يا رَبِّ!!\nهيحلف بالله إنه عمره ما شاف نعيم أبدا مع إنه كان أنعم أهل الدنيا،\nفي حين بقى إللي احنا شايفينه عايش في كرب وبؤس وهو من أهل الجنة ويتغمس فيها غمسة واحدة بس هينسى بعدها كل بؤس وألم وظلم وقهر اتعرض له\nرسول الله ﷺ بيقول:\nويُؤْتَى بأَشَدِّ النَّاسِ بُؤْسًا في الدُّنْيا، مِن أهْلِ الجَنَّةِ، فيُصْبَغُ صَبْغَةً في الجَنَّةِ، فيُقالُ له:\nيا ابْنَ آدَمَ هلْ رَأَيْتَ بُؤْسًا قَطُّ؟ هلْ مَرَّ بكَ شِدَّةٌ قَطُّ؟ \nفيَقولُ: لا، واللَّهِ يا رَبِّ ما مَرَّ بي بُؤْسٌ قَطُّ، ولا رَأَيْتُ شِدَّةً قَطُّ!!\nدي بس غمسة واحدة ومع ذلك خلت كل واحد فيهم ينسى هو كان عايش في إيه،\nفما بالكم باللي هيعيش فيهم بقى حياته هتبقى عاملة إزاي\nفمحدش يزعل لما يشوف ظالم أو كافر عايش في قصور ونعيم ورخاء والمؤمن عايش في بؤس وفقر وابتلاءات،\nالعبرة بالآخرة،\nعمر ما كانت الدنيا مقياس لمحبة ربنا للعبد أبدا، لو الدنيا تساوي عند ربنا جناح بعوضة ما سقى فيها كافر شربة ماء زي ما رسول الله ﷺ قال:\n\" لو كانتِ الدُّنيا تعدلُ عندَ اللهِ جناحَ بعوضةٍ ما سقى كافرًا منها شربةَ ماءٍ\"\nيعني هي أحقر عند ربنا من جناح البعوضة بكتير جدا، والدليل على كده إن ربنا مش بس سامح لهم إنهم يشربوا شربة مية دول كمان عندهم الأموال وعايشين براحتهم وعايشين في نعيم\nفاحنا ننفذ وصية رسول الله ﷺ بإننا نصبر،\nقال رسول الله ﷺ:\n\"اصْبِرُوا حتَّى تَلْقَوْنِي علَى الحَوْضِ\"\nنصبر شوية على الفقر....نصبر شوية على الأذى...نصبر شوية على فقد الأحبة وكل الابتلاءات إللي بنتعرض لها،\nوهي ساعات هنقضيها في الدنيا وبعدها ربنا يرزقنا الجنة برحمته وفضله إن شاء الله\nرسول الله ﷺ قعد شهر معتزل لنسائه، فلما عدى تسعة وعشرين يوم دخل رسول الله ﷺ على السيدة عائشة وكانت هي أول واحدة من زوجاته بدأ بها رسول الله ﷺ بعد ما انتهى الشهر،\nفقالت له:\n\"إنَّكَ أقْسَمْتَ أنْ لا تَدْخُلَ عَلَيْنَا شَهْرًا، وإنَّا أصْبَحْنَا لِتِسْعٍ وعِشْرِينَ لَيْلَةً أعُدُّهَا عَدًّا\"\nفقال لها رسول الله ﷺ:\n\"الشَّهْرُ تِسْعٌ وعِشْرُونَ\"\nوكان ساعتها الشهر ده تسعة وعشرين يوم مش ثلاثين، وهم كانوا معتمدين الشهور العربية مش الشهور الميلادية.\nبعد ما انتهى اعتزال رسول الله ﷺ لنسائه حصل الحدث الثاني إللي قلنا عليه وهو:\n◇ تخيِير زوجات رسول الله ﷺ بين البقاء معه أو إنه يطلقهن.\nنزلت الآية بتقول:\n\"يَا أَيُّهَا النَّبِيُّ قُلْ لأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلا ۩\nوَإِنْ كُنْتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا\"\nيعني ربنا بيأمر رسول الله ﷺ إنه يخيّر زوجاته ويقول لهم: لو انتم عايزين الحياة الدنيا وزينتها فخلاص أنا هطلقكم وهعطكيم نفقة المطلقة،\nوتقدروا بعد العِدة تتزوجوا باللي انتم عايزينه من إللي عنده أموال ويقدر يلبي لكم طلباتكم،\nلكن لو انتم عندكم استعداد تصبروا معايا على شدة الدنيا وعلى الفقر واخترتم إنكم تفضلوا معايا فربنا هيكافئكم بجزيل الثواب والأجر يوم القيامة\nأول واحدة عرض عليها رسول الله ﷺ التخيير هي السيدة عائشة رضي الله عنها، قال لها:\n\"إنِّي ذَاكِرٌ لَكِ أمْرًا، ولَا عَلَيْكِ أنْ لا تَعْجَلِي حتَّى تَسْتَأْمِرِي أبَوَيْكِ\"\nيعني أنا هعرض عليكِ حاجة ومش عايزك تستعجلي في الرد لحد ما تستشيري أمك وأبوكِ،\nوقال لها الآية، فقال السيدة عائشة رضي الله عنها:\nأفِي هذا أسْتَأْمِرُ أبَوَيَّ؟!\nفإنِّي أُرِيدُ اللَّهَ ورَسوله والدَّارَ الآخِرَة.\nيعني هي دي حاجة محتاجة أستشير فيها أبويا وأمي؟!\n طبعا أختار ربنا ورسوله والدار الآخرة،\nوخيّر رسول الله ﷺ باقي زوجاته وكلهم قالوا زي ما قالت السيدة عائشة، اختاروا الله ورسوله والدار الآخرة.\nالسؤال بقى:\n☆إيه السبب في كل الأحداث إللي حصلت دي\nشوفوا،\nالعلماء ذكروا أسباب كتير، لكن احنا هنتكلم عن أهم الأسباب دي بالتفصيل،\n◇السبب الأول:\nإفشاء حفصة لعائشة سر رسول الله ﷺ كان قالها متقوليهوش لحد،\nيعني حصل حاجة بين رسول الله ﷺ وبين السيدة حفصة فقالها متقوليش لحد فراحت قالت للسيدة عائشة،\nوهنعرف بالتفصيل إن شاء الله إيه هو السر ده،\nوالحادثة دي كانت سبب رئيسي لاعتزال رسول الله ﷺ لنسائه.\n◇السبب الثاني:\nإن زوجات رسول الله ﷺ أكثروا عليه في طلب النفقة.\nوالحادثة دي كانت سبب في نزول آية التخيير إللي قلنا عليها.\n☆احنا هنبتدي بشرح السبب التاني لأن قصة إفشاء سر رسول الله ﷺ طويلة ومش هينفع أحكيها النهاردة فهنخليها المرة الجاية إن شاء الله\nاحنا قلنا قبل كده إن زوجات رسول الله ﷺ كانوا بيجتموا كل يوم في بيت الزوجة إللي رسول الله ﷺ هيبات عندها ويقعدوا كلهم مع بعض ومعاهم رسول الله ﷺ،\nوفي الليل كل واحدة ترجع لبيتها وبيوتهم كانوا جنب بعض،\nفي يوم كانوا كلهم متجمعين في بيت السيدة عائشة وكان ده يومها،\nجاء أصحاب رسول الله ﷺ يستأذنوا للدخول على رسول الله ﷺ فلم يُؤذن لهم،\nيعني كل واحد ييجي يستأذن لا يُؤذن له بالدخول وبقى في تجمُّع عند باب رسول الله ﷺ،\nفجاء أبو بكر الصديق رضي الله عنه فاستأذن في الدخول فلم يُؤذن له هو كمان\nفقعد مع الناس إللي اتجمعت عند باب رسول الله ﷺ،\nوبعدها جاء عمر بن الخطاب رضي الله عنه فاستأذن بالدخول فلم يُؤذن له وقعد مع أبو بكر وباقي الصحابة،\nوالسبب في عدم السماح بالدخول لكل إللي جاء واستأذن هو إن رسول الله ﷺ كان مشغول بالكلام مع زوجاته،\n◇عايزاكم بس يا جماعة تتخيلوا  كده إن أمهات المؤمنين رضي الله عنهن مكنوش ملائكة كانوا بشر وفيهم من الصفات البشرية إللي موجودة في النساء عادي جدا\nيعني تخيلوا واحد متزوج من أربع نساء وقاعد بيتكلم مع الأربعة، تخيلوا الدماء إللي ممكن تسيل من مجرد النقاش بس\nفرسول الله ﷺ كان قاعد مع زوجاته إللي الواحدة فيها كانت ممكن تهجر رسول الله ﷺ ومتكلموش وتزعل منه،\nفكان بيت رسول الله ﷺ زي أي بيت فيه مشاكل وشد وجذب\nفهمّ في الوقت ده كانوا عمالين بيكلموا رسول الله ﷺ وفي بينهم حوارات ساخنة وشد وجذب، فدماغه هتبقى فاضية إزاي إنه يقابل حد من الصحابة\nبعد شوية، نقدر نقول لما الحوار وصل لنقطة معينة وسكتوا، أَذِن رسول الله ﷺ لأبي بكر وعمر فقط إنهم يدخلوا على رسول الله ﷺ؛\nلأن بناتهم حفصة وعائشة رضي الله عنهما كانوا موجودين في المجلس،\nفلما دخلوا لقوا إن زوجات رسول الله ﷺ متجمعين حوله وهم في حالة من السكوت الغير طبيعي،\nشوفوا كده لما ندخل على اتنين كانوا لسه متخانقين أو شادين مع بعض في الكلام وبيبقى في سكوت كده مش طبيعي ونحس إن في حاجة مش مضبوطة،\nأهه نفس الإحساس ده كان عند أبو بكر وعمر، لقوا إن الوضع مش مريح وفي حاجة مش طبيعية، هم ميعرفوش المشكلة فين ولا إيه إللي حصل،\nوطبعا رسول الله ﷺ كان واضح عليه إنه متضايق وساكت سكوت مش طبيعي،\nمحدش قدر يسأل رسول الله ﷺ إيه إللي مضايقه أو فين المشكلة،\nكل إللي كان شاغل عمر ساعتها إزاي يطلع رسول الله ﷺ من الحالة إللي هو فيها دي ويخليه يضحك،\nفقال عمر لرسول الله ﷺ:\nيا رسول الله، لو رأيْتَ بنتَ زَيدٍ- زوجة عمر-سألَتْني النَّفقةَ آنِفًا، فوجَأْتُ عُنُقَها\nيعني يا رسول الله لو شوفتني لما زوجتي طلبت من النفقة وأنا معنديش حاجة أديهالها قمت أطعن في رقبتها بإيدي وأقولها انا معنديش حاجة...أنا معنديش حاجة،\nفرسول الله ﷺ لما سمع كلام عمر ضحك لدرجة إن أضراسه ظهرت ﷺ، وهو ده إللي كان عمر عايزه، إنه يلطف الجو عن طريق إنه يضحه،\nوسبحان الله الموقف إللي حكاه عمر مع زوجته جه في صميم الموضوع إللي زوجات رسول الله ﷺ بيكلموه عنه\nقال رسول الله ﷺ لعمر:\n\"هُنَّ حَوْلي كما تَرى يَسألْنَني النَّفقةَ\"\nيعني زي مانت شايف هم متجمعين حولي بيطلبوا مني زيادة في النفقة،\nوالسبب في كده إن زوجات رسول الله ﷺ لما شافوا إزاي المسلمين انتصروا على أعادءهم، دولة الإسلام بقت لها مكانة وشافوا الغنائم إللي بتتوزع على المسلمين وظهر أثر النعم دي على نساء المسلمين من المهاجرين والأنصار،\nزي مثلا لما واحدة زوجها يبقى معاه فلوس ويروح يوزّع على الناس كلها وهي ميديهاش أي حاجة زيادة، أكيد هتطلب منه هي كمان ده إذا معملتهاش خناقة\nفكان طبيعي إن نفوسهن تميل إلى الرزق الحلال من الدنيا فطلبوا من رسول الله ﷺ إنه يوسّع عليهن في النفقة،\nودي طبيعة المرأة، بتميل أكثر من الرجل لحياة الرفاهية والراحة،\nلكن زوجات رسول الله ﷺ مينفعش يكونوا زي باقي النساء،\nربنا أراد إنه يقوّم الطبيعة دي عندهم ويخليهم مَثَل وقدوة للنساء في الزهد وتحمل أعباء الدعوة على مدى الزمن\nفعمر وأبو بكر لما سمعوا رسول الله ﷺ بيقول كده؛ كل واحد فيهم توجه لبنته عايز يضربها وكل واحد فيهم بيقول لبنته:\nتَسألانِ رسولَ اللهِ ﷺ ما ليس عنده\nيعني بتطلبوا من رسول الله ﷺ حاجة مش عنده ومش هيقدر يعملهاكم،\nفنهى رسول الله ﷺ أبا بكر وعمر عن ضرب عائشة وحفصة رضي الله عنهما،\nفزوجات رسول الله ﷺ قالوا:\n\"واللهِ لا نَسألُ رسولَ اللهِ ﷺ بعدَ هذا المَجلِسِ ما ليس عنده\"\nيعني بعد النهاردة مش هنطلب من رسول الله ﷺ حاجة مش عنده تاني\nفكانت الحادثة دي سبب نزول آية التخيير إللي قلناها.\nبالنسبة بقى لقصة إفشاء السر، فدي هنعرفها الجزء جاي إن شاء الله"}, {"n": 230, "l": "الجزء 204 | احداث السنه التاسعه من الهجرة | قصة إفشاء سر رسول الله", "u": "", "t": "##قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وأربعة\n#أحداث_السنة_التاسعة_من_الهجرة\n#قصة_إفشاء_سر_رسول_الله\nهنتكلم النهاردة إن شاء الله عن السر إللي رسول الله ﷺ أسرّه لإحدى زوجاته وبعدين هي أفشت السر ده،\nربنا بيقول في سورة التحريم:\n\"وَإِذْ أَسَرَّ النَّبِيُّ إِلَى بَعْضِ أَزْوَاجِهِ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِ وَأَظْهَرَهُ اللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُ وَأَعْرَضَ عَنْ بَعْضٍ فَلَمَّا نَبَّأَهَا بِهِ قَالَتْ مَنْ أَنْبَأَكَ هَذَا قَالَ نَبَّأَنِيَ الْعَلِيمُ الْخَبِيرُ ۩ \nإِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِنْ تَظَاهَرَا عَلَيْهِ فَإِنَّ اللَّهَ هُوَ مَوْلَاهُ وَجِبْرِيلُ وَصَالِحُ الْمُؤْمِنِينَ وَالْمَلَائِكَةُ بَعْدَ ذَلِكَ ظَهِيرٌ\"\nالعلماء اختلفوا في السرّ إللي قاله رسول الله ﷺ لإحدى زوجاته على قولين:\n◇القول الأول هو قصة العسل وهي:\nإن رسول الله ﷺ كان بيحب العسل والحلوى وكان من عادته ﷺ إنه بعد العصر بيطوف على نسائه ويقعد مع كل واحدة شوية، \nفدخل عند زوجته زينب بنت جحش رضي الله عنها فتأخر عندها على غير المعتاد والموضوع اتكرر فالسيدة عائشة غارت واتضايقت فسألت عن السبب إللى بيخلى رسول الله ﷺ يتأخر عند زينب فعرفت إن عندها عسل وكانت تسقيه رسول الله ﷺ،\nففكرت في حيلة عشان متخليهوش يشرب العسل تاني وبالتالي ميتأخرش عند زينب،\nفكلمت السيدة حفصة وقالت لها خلينا نحتال عليه حيلة،\nوإللي يدخل عليها الأول تسأله:\nأكلت مَغَافِير؟!\n☆والمغافير دي عبارة عن عسل طعمه حلو لكن له رائحة كريهة،\nفهمّ لما يقولوا كده لرسول الله ﷺ هيفهم إن العسل إللي أكله عند زينب رائحته كريهة،\nورسول الله ﷺ كان حريص إن رائحة فمه تكون رائحة طيبة، فكده هيمنع نفسه من إنه يشرب عسل تاني وبالتالي ميتأخرش عند زينب رضي الله عنها\nفلما دخل رسول الله ﷺ على حفصة وعائشة كل واحدة في بيتها، هم الاتنين سألوه نفس السؤال،\nفرد عليهم رسول الله ﷺ وقال لهم: لا، ولكني شربت عسل عند زينب!\nفهنا رسول الله ﷺ فِهم إن العسل رائحته كريهة فحلف بالله إنه مش هيشرب منه تاني وقال لحفصة متقولش لحد على الموضوع ده،\nلكنها قالت لعائشة رضي الله عنها على نجاح الخطة بتاعتها بإن رسول الله ﷺ مش هيشرب عسل تاني عند زينب\n☆ملحوظة:\nفي رواية تانية بتقول إن إللي كان بيشرب رسول الله ﷺ عندها العسل هي حفصة وإن إللي كانوا في الخطة مع السيدة عائشة هنّ السيدة سوْدة والسيدة صفية،\nلكن الرواية الأصح هي إللي احنا حكيناها؛ لأنها توافق ظاهر القرآن، ربنا بيقول:\n\"إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِنْ تَظَاهَرَا عَلَيْهِ\"\nفالكلام هنا بصيغة المثنى، ولو كانوا أكثر من اتنين كان ربنا خاطبهم بصيغة الجمع،\nوكمان في حديث عبد الله بن عباس لما سأل عمر رضي الله: مَن المرأتان من أزواج النبي ﷺاللتان قال الله تعالى:\n \"إِنْ تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا\"\nقال عمر: هما عائشة وحفصة\n◇توضيح بقى يا جماعة عشان  محدش يفهم غلط\n السيدة عائشة لم تكذب ولم تحرّض غيرها على الكذب،\nكل إللي حصل إنها احتالت في الكلام، يعني سألت مجرد سؤال بس إذا كان رسول الله ﷺ أكل مغافير أو لأ،\nفالاحتيال هنا كان بالتعريض مش صريح كذب وإلا فالكلام مبقاش حيلة ده بقى كذب وده محرم،\nوحاشا أمهات المؤمنين إنهن يقعن في الكذب\nوالسيدة عائشة كانت صغيرة في السن وكانت بتحب رسول الله ﷺ بشدة وهي عارفة إنها أحب زوجات رسول الله ﷺ إلى قلبه فكانت بتغير غيرة شديدة جدا فكان رسول الله ﷺ بيعذرها في تصرفاتها،\nوالسيدة عائشة والسيدة حفصة تابوا من الاحتيال ده على رسول الله ﷺ، والفعل إللي عملوه ده كان من الصغائر المعفو عنها وخصوصا إن لهن من الحسنات والفضل إللي يكفّر الخطأ ده\n◇القول الثاني هو قصة تحريم رسول الله ﷺ أمة على نفسه،\nالقصة بتقول:\nأنَّ رسولَ اللهِ ﷺ كانت له أمةٌ يطؤُها ؛ فلم تزلْ به عائشةُ وحفصةُ حتَّى حرَّمها على نفسِه ؛ فأنزل اللهُ عزَّ وجلَّ : \n\"يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللهُ لَكَ\"\n《الحديث ده صحيح موجود في صحيح النسائي》\nوالحديث معناه إن رسول الله ﷺ كان عنده أمة يعاشرها معاشرة الأزواج، فعائشة وحفصة فضلوا ورا رسول الله ﷺ لحد ما رسول الله ﷺ حرّمها على نفسه عشان يرضيهم وميزعلهمش،\nإزاي بقى وصلوه لكده وعملوا إيه الله أعلم\nمفيش حديث صحيح بيقول إيه إللي حصل بالتفصيل ولا مين هي الأمة دي،\nلكن يا جماعة في ثلاثة وعشرين حديث جاء فيهم إن الأمة دي هي مارية وإن إللي حصل إن في يوم من الأيام السيدة حفصة استأذنت رسول الله ﷺ إنها تروح تزور أباها عمر رضي الله عنه، فأَذِن لها رسول الله ﷺ، وبعدين رسول الله ﷺ أرسل لمارية إنها تأتي لرسول الله ﷺ في بيت حفصة،\nفعاشرها رسول الله ﷺ معاشرة الأزواج في بيت حفصة،\nفجاءت حفصة رضي الله عنها فلقت مارية في بيتها،\nفقالت لرسول الله ﷺ:\nيا رسول الله في بيتي وفي يومي وعلى فراشي؟\nفرسول الله ﷺ قالها إنها محرمة عليه وحلف إنه مش هيقرب لها وقال لها متقوليش لحد،\nفراحت السيدة حفصة بعدها وأخبرت عائشة إن رسول الله ﷺ حرم مارية على نفسه عشان خاطرها.\nالثلاثة وعشرين حديث إللي ورد فيهم التفاصيل إللي قلناها دي كلهم إما ضعيف أو ضعيف جدا أو موضوع\nلكن العلماء قالوا إن بمجموع الأحاديث دي كلها ده معناه إن القصة لها أصل، \nوكمان الأحداث بصفة عامة بتشير إن الأَمة إللي حرمها رسول الله ﷺ على نفسه هي مارية لأنها كانت جميلة وكان زوجات رسول الله ﷺ بيغاروا منها وخصوصا إنها أنجبت ولد لرسول الله ﷺ.\nفاحنا إللي يهمنا هنا إن رسول الله ﷺ حرّم على نفسه شيء عشان يرضي زوجاته،\nوطبعا بسبب إن رسول الله ﷺ حرم على نفسه حاجة حلال سواء كان العسل أو مارية؛ ربنا أنزل القرآن يعاتبه فيه، قال:\nيَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ ۖ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ وَاللَّهُ غَفُورٌ رَّحِيمٌ\"\nوالآية الواحدة ممكن يكون لها أكثر من سبب نزول،\nيعني قصة تحريم رسول الله ﷺ العسل على نفسه حصلت في مرة،\nومرة تانية حصلت قصة تحريم مارية على نفسه ﷺ، فالموقفين دول كانوا سبب في نزول آية التحريم،\nزي مثلا كده لو حصلت حادثة على طريق أدت لقتل خمس أشخاص، وحصلت حادثة تانية أدت لقتل بعض البهائم،\nوحادثة ثالثة أدت لحصول انفجار،\nفإدارة المرور أصدرت قرار إن السرعة على الطريق إللي حصلت عليه الحوادث لا تزيد عن مائة كيلو متر مثلا،\nفواحد هيقول القرار ده نزل بسبب مقتل الخمس الأشخاص،\nوالتاني يقول لأ ده كان بسبب مقتل البهائم، وثالث يقول ده كان بسبب الانفجار،\nوكلهم كلامهم صحيح، فنقدر نقول إن القانون اتعمل عشان الثلاثة حوادث دول،\nولله المثل الأعلى بقى، ربنا أنزل آية التحريم بسبب الموقفين إللي حكيناهم دول.\nفربنا بيقول لرسول الله ﷺ في الآية ليه تحرم على نفسك حاجة ربنا أَحلّها لك عشان ترضي أزواجك؟!\nوربنا حذر زوجات رسول الله ﷺ لما اجتمعن عليه في الغيرة، يعني كل واحدة غيرانة من التانية وبالتالي هتسبب لرسول الله ﷺ مشاكل أو أذى،\nسواء بقى إنه يحرّم على نفسه ما أحل الله له، أو يقعد يفض بين المنازعات بينهن أو...أو...، قال الله عز وجل:\n\" عَسَى رَبُّهُ إِنْ طَلَّقَكُنَّ أَنْ يُبْدِلَهُ أَزْوَاجًا خَيْرًا مِنْكُنَّ مُسْلِمَاتٍ مُؤْمِنَاتٍ قَانِتَاتٍ تَائِبَاتٍ عَابِدَاتٍ سَائِحَاتٍ ثَيِّبَاتٍ وَأَبْكَارًا \"\nوالسبب إن ربنا شدد على زوجات رسول الله ﷺ وحذرهم كده وأنزل قرآن يعاتب رسول الله ﷺ إنه حرم على نفسه شيء حلال هو إن بيت رسول الله ﷺ هو المثال والقدوة للمسلمين والمفروض إنهم يقلدوا البيت النبوي ده،\nعشان كده ربنا أراد أن يُنَزّه بيت النبوة من ألاعيب النساء وحيلهنّ لكسب قلب الزوج وتحوّله عن ضرائرهن بسبب الغيرة النسائية.\nيعني تخيلوا كده مثلا لو الصورة إللي ترسّخت في أذهان المسلمين إن بيت رسول الله ﷺ عبارة عن ميدان للمؤامرات والحيل، وإن تصرفات رسول الله ﷺ تتأثر بالسلب أو الإيجاب بسبب الأحداث دي،\nوإن أقواله أو أفعاله ممكن تتبنى على أمور متوهمة؛ \nالنتيجة طبعا هتكون زعزعة الثقة بشخص رسول الله ﷺ وخاصة بما يتعلق بالجانب العائلي من حياته\nهقول لكم مثال عشان تفهموا المعنى بصورة أوضح\nلو واحد متزوج واحدة وبين زوجته وبين أمه غيرة وكل شوية مشاكل بينهم،\nفهو عشان يحل مشكلة معينة بينهم أخد قرار إنه مش هيعمل الحاجة الفلانية،\nفتقوم أمه تقول أه، مانت بتعمل كذا عشان ترضي مراتك\nوتيجي زوجته تقول انت بتعمل كده عشان والدتك وأنا مليش أي اعتبار\nمع إن هو ممكن يكون هو المتضرر أصلا من القرار إللي أخده ده\nفتخيلوا بقى كل مرة هتحصل مشكلة لا أمه هتثق في قرار ولا زوجته هتثق في قراره؛ لأن كل واحدة هتفكر إنه عمل كده عشان يرضي التانية،\nوهو ده موقف رسول الله ﷺ هنا، طبعا مع الفارق بين وضع الزوجة والأم وحقوق كل واحدة\nفلما نلاقي رسول الله ﷺ كل شوية ياخد قرارات عشان محدش من زوجاته يزعل هيبقى كده بياخد القرار حسب هوى زوجاته مش لأن ده هو القرار الصحيح،\nوكده الناس هتفقد الثقة في آراء وقرارات رسول الله ﷺ،\nوفقد الثقة ده هيبق  طبيعي على فكرة، \nيعني أنا لما ألاقي كل شوية واحد بياخد قرارات على حسب هواه أو على هوى حد تاني أكيد عمري ما هثق في رأيه حتى لو رأيه في موضوع معين هو الصح، بس خلاص مبقاش في ثقة\nولأن رسول الله ﷺ قدوة لينا في كل تعاملاته فمينفعش نفقد الثقة فيه،\nعشان كده ربنا صحح المسار وقال إن الصح كذا ودي حريتك الشخصية تاكل إللي تاكله ما دام مش حرام،\nهم إللي محتاجين يضبطُوا غيرتهم\nوده يعلمنا إننا منحاولش أبدا نرضي البشر لأننا مستحيييل هنقدر نرضيهم لأنهم متقلبين أصلا ومحدش بيثبت على حال،\nلكن نمشي على القواعد إللي ربنا وضعهالنا وتكون غايتنا هي رضا ربنا وبس\nفكان من كرم أخلاق رسول الله ﷺ إنه ضحّى بحاجة بيحبها عشان ميزعلش زوجاته،\nلكن ربنا بيقول إن ده مش صح، متحرّمش على نفسك حاجة حلال عشان ترضي نزوة أو هوى امرأة غيور،\nامشي على المنهج الصحيح بدون إفراط أو تفريط\nوعلى فكرة يا جماعة ده إللي مضيعنا\nإننا دايما بنضحي حتى بحقوقنا عشان نرضي ناس معينة في حياتنا وده بيخليهم يستغلونا وبنضيع نفسنا أكتر، والمشكلة إننا نرجع نشتكي من أفعالهم، واحنا أصلا إللي غلطانين عشان إديناهم المجال لكده،\nكل حاجة لازم تمشي بتوازن:\n《إن لربك عليك حقا، وإن لنفسك عليك حقا، ولأهلك عليك حقا، فأعطِ كل ذي حق حقه》\nمن حق رسول الله ﷺ إنه يستمتع بما أحله الله له، ومش من حق زوجات رسول الله ﷺ إنهن يضطروه إنه يحرم نفسه من الحق ده\nفبعد ما ربنا عاتب رسول الله ﷺ على تحريمه على نفسه ما أحل الله له وإفشاء حفصة لسره، وكمان مع موقف طلب زوجات رسول الله ﷺ زيادة النفقة ومواقف تانية، كل ده أدى إن رسول الله ﷺ يغضب ويحلف إنه يعتزلهن شهرا زي ما حكينا.\nوبكده انتهت قصة اعتزال رسول الله ﷺ لنسائه،\nلو في أي نقطة مش واضحة قولوا في التعليقات وانا هوضحها في بداية الجزء الجاي  إن شاء الله\nالمرة الجاية إن شاء الله هنكمل باقي أحداث السنة التاسعة، وهنعرف إيه حكاية زواج علي بن أبي طالب من بنت أبي جهل"}, {"n": 231, "l": "الجزء 205 | منع زواج علي من ابنة ابي جهل", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وخمسة\n#أحداث_السنة_التاسعة_من_الهجرة\n#منع_زواج_علي_من_ابنة_أبي_جهل\nهنتكلم النهاردة إن شاء الله عن قصة منع رسول الله ﷺ لعلي بن أبي طالب من إنه يتزوج بنت أبي جهل\nعلي بن أبي طالب هو زوج فاطمة بنت رسول الله ﷺ زي ماحنا عارفين، \nوكمان احنا عارفين إن في زمن رسول الله ﷺ وقبل حتى زمن رسول الله ﷺ تعدد الزوجات كان شيء عادي جدا\nيعني الرجل كان ممكن يبقى عنده تسع زوجات وأكثر كمان ومفيش أي مشكلة، وده كان قبل الإسلام،\nأما بعد الإسلام فتعدد الزوجات اتحدد بأربع زوجات فقط ما عدا ما كان في حق رسول الله ﷺ وإنه وضعه كان حاجة خاصة بيه،\nفالصحابة كان فيهم إللي عنده زوجة واحدة أو اثنين أو ثلاثة أو حتى أربعة،\nعلي بن أبي طالب كان متزوج من فاطمة فقط ومكنش عنده زوجة تانية، فكان عايز يتزوج من امرأة تانية فخطب بنت أبي جهل،\nفلما فاطمة عرفت راحت لرسول الله ﷺ وقالت له:\n\"إِنَّ قَوْمَكَ يَتَحَدَّثُونَ أَنَّكَ لَا تَغْضَبُ لِبَنَاتِكَ، وَهَذَا عَلِيٌّ نَاكِحًا ابْنَةَ أَبِي جَهْلٍ\"\nيعني بتقول لرسول الله ﷺ إن الناس بيقولوا إنك مش بتغضب لبناتك لو حد آذاهم، وعلي هيتزوج بنت أبي جهل ودي حاجة تؤذي فاطمة،\nوكان بعد ما علي خطب بنت أبي جهل جاء لرسول الله ﷺ بني هشام بن المغيرة إللي همّ قوم أبي جهل يستأذنوا رسول الله ﷺ إنهم يزوّجوا ابنتهم لعلي بن أبي طالب،\nفقام رسول الله ﷺ يخطب في الناس وقال لهم:\n\"إنَّ بَنِي هِشَامِ بنِ المُغِيرَةِ اسْتَأْذَنُوا في أنْ يُنْكِحُوا ابْنَتَهُمْ عَلِيَّ بنَ أبِي طَالِبٍ،\n فلا آذَنُ، ثُمَّ لا آذَنُ، ثُمَّ لا آذَنُ، إلَّا أنْ يُرِيدَ ابنُ أبِي طَالِبٍ أنْ يُطَلِّقَ ابْنَتي ويَنْكِحَ ابْنَتَهُمْ\"\nيعني رسول الله ﷺ بيقول إن أهل بنت أبي جهل استأذنوا رسول الله ﷺ إنهم يزوجوا بنتهم لعلي لكن رسول الله ﷺ رفض تماااما إلا بشرط وهو إن علي رضي الله عنه يطلق فاطمة ويتزوج ابنتهم،\nوقال رسول الله ﷺ:\n \"فَإِنِّي أَنْكَحْتُ أَبَا الْعَاصِ بْنَ الرَّبِيعِ فَحَدَّثَنِي فَصَدَقَنِي، وَوَعَدَنِي فَوَفَى لِي، وإِنَّمَا فَاطِمَةُ بَضْعَةٌ مِنِّي يُؤْذِينِي مَا آذَاهَا\nوإني لستُ أُحرّمُ حلالاُ، ولكن وَاللَّهِ لَا تَجْتَمِعُ بِنْتُ رَسُولِ اللَّهِ وَبِنْتُ عَدُوِّ اللَّهِ عِنْدَ رَجُلٍ وَاحِدٍ أَبَدًا،\nوإِنَّ فَاطِمَةَ مِنِّي، وَإِنِّي أَتَخَوَّفُ أَنْ تُفْتَنَ فِي دِينِهَا\"\nيعني رسول الله ﷺ بيقول إنه زوّج بنته زينب لأبي العاص بن الربيع وكان عاهده إنه يحسن إليها ويرعاها ولا يؤذيها بأي طريقة، فوَفّى أبو العاص بعهده مع رسول الله ﷺ،\nحتى إن قريش كانت طلبت من أبي العاص إنه يطلق زينب بنت رسول الله ﷺ بعد النبوة زي ما عمل أبناء أبي لهب لكن أبو العاصِ رفض،\nواحنا اتكلمنا بالتفصيل عن الموضوع ده قبل كده وحكينا قصة زينب مع أبي العاص\nفدلوقتي علي عايز يتزوج بنت أبي جهل ودي حاجة تؤذي فاطمة وهي أحب بنات رسول الله ﷺ إليه وأي حاجة تؤذيها بتؤذي رسول الله ﷺ، وأذية رسول الله ﷺ محرمة\nورسول الله ﷺ بيقول إنه لا يحرّم حلال، يعني التعدد ربنا شرعه وهو مباح لكن في أسباب منعت زواج علي من بنت أبي جهل، هم أربعة أسباب:\n◇السبب الأول:\nلا تجتمع بنت رسول الله ﷺ وبنت عدو الله في عصمة رجل واحد،\nولو تفتكروا العداء إللي كان بين رسول الله ﷺ وبين أبي جهل وكم المحاولات إللي أبو جهل حاول فيها يقتل رسول الله ﷺ وفي الآخر فشل، \nده غير إن أبا جهل كان بينتهز أي فرصة عشان يؤذي رسول الله ﷺ بأي طريقة،\nكل ده وفاطمة رضي الله عنها شايفة وعارفة، وبنت أبي جهل استمرت على الكفر لحد فتح مكة، وأسلمت بعد الفتح،\nفخلال السموات دي كلها قبل إسلامها كان في قلبها الكُره لرسول الله ﷺ وللإسلام،\nفإزاي تتساوى بنت رسول الله ﷺ سيدة نساء العالمين مع ابنة فرعون هذه الأمة كما قيل عن أبي جهل وإن كان الحديث فيه ضعف،\nلكن هو عدو الله بدون أدنى أشك وكمان أشد الناس عداوة لرسول الله ﷺ\nأيوة الإسلام يمسح كل إللي قبله لكن يستحيل هم الاتنين يتساووا في المنزلة،\nيعني ربنا نفسه بيقول:\n\"لَا يَسْتَوِي مِنكُم مَّنْ أَنفَقَ مِن قَبْلِ الْفَتْحِ وَقَاتَلَ ۚ أُولَٰئِكَ أَعْظَمُ دَرَجَةً مِّنَ الَّذِينَ أَنفَقُوا مِن بَعْدُ وَقَاتَلُوا\"\nيعني إللي أسلموا قبل فتح مكة وقاتلوا يستحيل تتساوى منزلتهم من إللي أنفقوا من بعد فتح ومكة وجاهدوا،\nإللي أنفقوا وجاهدوا قبل فتح مكة أعظم درجة،\nوخلونا منطقيين يا جماعة مين تقبل إن زوجها يتزوج امرأة أبوها كان أشد الناس عداوة لأبو الزوجة الأولى وحاول يقتله أكثر من مرة\n ◇وده هياخدنا للسبب التاني وهو قول رسول الله ﷺ:\n\"إِنَّ فَاطِمَةَ مِنِّي، وَإِنِّي أَتَخَوَّفُ أَنْ تُفْتَنَ فِي دِينِهَا\"\nيعني رسول الله ﷺ خايف إن فاطمة تفتن في دينها بسبب الغيرة،\nيعني هو خاف أن تدفعها الغيرة لفعل ما لا يليق بحالها ومنزلتها وهي سيدة نساء العالمين،\nواحنا عارفين إن الغيرة من طبع المرأة، فتخيلوا لما تجتمع الغيرة إللي في طبع المرأة مع الضيق إن زوجها تزوج من بنت عدو الله وعدو رسوله،\nأيوة لا تزر وازرة وزر أخرى ومحدش بيشيل ذنب حد لكن الصحابة كانوا بشر وطبيعي جدا إنهم يتأثروا بحاجة زي كده،\nفهيكون إيه الوضع بقى لو السيدة فاطمة اتحطت في موقف يضطرها إنها تتصرف بتصرف غير لائق بها وبمكانتها، \nخاصة وأنها فقدت أمها من صغرها وبعدين فقدت أخواتها واحدة بعد واحدة، فلم يتبقّ لها أحد تستأنس به من إللي ممكن يخفف عليها الأمور إذا وقعت في الغيرة\nفالحل إننا نقفل الباب ده خالص من البداية\n◇السبب الثالث:\nالزواج ده فيه إيذاء لفاطمة، وإيذاؤها يؤذي رسول الله ﷺ  وإيذاء النبي ﷺ من كبائر الذنوب،\nفلما السيدة فاطمة تتعرض لأذى نفسي بسبب زواج علي من ابنة عدو الله وكمان ممكن أقارب الزوجة فيهم مشركين فممكن يتعرضوا للسيدة فاطمة بأي أذى،\nوطبيعي إن رسول الله ﷺ كأب يتأذى من إللي بتتأذى منه ابنته وأحب بناته إليه،\nفكده علي رضي الله عنه هيقع في كبيرة من الكبائر، فرسول الله ﷺ أشفق عليه من كده،\nوعلي رضي الله عنه لو كان يعرف إن خطبته لابنة أبي جهل ممكن يكون فيها أذى لرسول الله ﷺ عمره ما كان هيفكر إنه يخطبها أساسا،\nفلما عرف، على طول ترك خطبتها والزواج منها\n◇السبب الرابع:\nتعظيم لحق فاطمة وبيان لمكانتها ومنزلتها، يعني المرأة بصفة عامة منزلتها من منزلة زوجها،\nيعني مثلا لما نتكلم عن زوجة عمر بن الخطاب هنقول دي زوجة الفاروق عمر،\nلما نتكلم عن فلانة بنقول دي زوجة الرئيس أو الزعيم فلان،\nفهي اكتسبت مكانتها بسبب زوجها،\nمكانة المرأة بتبقى أعلى بزيادة لما تكون هي نفسها لها منزلة عالية،\nيعني واحدة سيدة أعمال مشهورة ومتزوجة كمان رجل أعمال مشهور، أكيد وضعها هيبقى مختلف عن المرأة العادية إللي متزوجة رجل أعمال فقط،\nفالسيدة فاطمة مكانتها عالية وهي سيدة نساء العالمين،\nفلما مع المكانة دي تكون متزوجة من واحد من المبشرين بالجنة وكمان هو الفدائي إللى فدى رسول الله ﷺ بروحه يوم الهجرة وإللي قال عليه رسول الله ﷺ إنه رجل يحبه الله ورسوله،\nيبقى أكيد مكانتها هتبقى فوق الكل ومينفعش تتساوى مع أي حد تاني\nكده احنا فهمنا مجمل القصة بصفة عامة، خلونا بقى نجاوب على كم سؤال كده ممكن ييجي على بالنا:\n☆السؤال الأول:\nهل معنى إن رسول الله ﷺ يمنع زواج علي يبقى هو كده حرم شيء أباحه الله؟\nلأ، رسول الله ﷺ لم يحرم شيء وهو بنفسه قال كده،\nقال:\n\"وإني لستُ أُحرّمُ حلالاُ\"\nيعني يا جماعة التعدد حلال ومباح وأنا مش بخالف أمر ربنا زلا بحرم شيء مباح، لكن مش هينفع علي يتزوج بنت أبي جهل بالذات عشان الأسباب إللي قلناها دي،\nفهو لو عايز يتزوج بنت أبي جهل يطلق فاطمة\n☆طبعا السؤال إللي هييجي هنا وهو السؤال الثاني:\nهل معنى كده إن المرأة لو أراد زوجها إنه يتزوج عليها  تشترط عليه إن يطلقها في مقابل إنه يتزوج بالزوجة الثانية\nالزواج من امرأة تانية من حق الزوج والمرأة ملهاش إنها تعترض، ولا يجب على الزوج إنه يستأذنها من زواجه من امرأة أخرى ولا يُشترط رضا الزوجة عشان زوجها يتزوج من امرأة أخرى،\nلكن من حُسن العشرة إنه يُطيِّب خاطرها باللي يخفف عنها الآلام إللي هي من طبيعة النساء في الموضوع ده،\nومينفعش تطلب الطلاق لمجرد إن زوجها هيتزوج من امرأة أخرى، لأن رسول الله ﷺ قال:\n\" أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا طَلاقًا فِي غَيْرِ مَا بَأْسٍ فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّة\"\nيعني أي واحدة هتطلب من زوجها الطلاق بدون سبب واضح أو ضرر واقع عليها فهي حتى مش هتشم رائحة الجنة وده كناية عن بُعدها عن الجنة وإنها لن تدخلها مع أوائل من يدخلها\n◇ممكن حد يقول طيب ماهو أكيد هيقع عليها ضرر نفسي بسبب الزواج التاني ده وأكيد ده سبب إنها تطلب الطلاق\nطيب وهي هتعرف منين إنها هيقع عليها ضرر نفسي من غير ما تخوض التجربة فعلا وتصبر وتحتسب وتجرب إذا كان هيقع عليها ضرر نفسي ولّا لأ\nوخصوصا يعني إن ربنا لا يكلف نفسا إلا وسعها، فمعنى إن ربنا أباح التعدد يبقى دي حاجة المرأة تقدر تحتملها،\nأيوة محتاجة صبر واحتساب زيها زي أي بلاء الواحد بيتعامل معاه\nلكن في نساء أول ما زوجها يجيب سيرة زواج تاني تقول طلقني،\nفين هنا البأس والضرر إللي وقع عليها عشان تطلب الطلاق؟\nمفيش\nامتى بقى يكون من حقها فعلا تطلب الطلاق؟!\nإذا الزوج تزوج عليها وكان عادل بينها وبين الزوجة التانية وهي صبرت واحتسبت وجاهدت نفسها واستعانت بالله وبعد كل ده مقدرتش تستحمل وخافت على نفسها إنها لا تؤدي حقوق زوجها فساعتها تقدر تطلب الطلاق،\nولو زوجها رفض من حقها تختلع منه بإنها ترد عليه المهر وتنفصل عنه\n☆طيب سؤال كمان،\nهل يجوز للمرأة إنها تشترط على المتقدم لها إنه لا يتزوج من امرأة أخرى أو يكتبوا مثلا الشرط ده في العقد\nالمسألة دي على خلاف بين العلماء،\n◇بعض العلماء قالوا إن الشرط ده باطل ولا يجوز وشرط فاسد لأنه مُخالف لما شرعه الله ولنص الآية:\n\"فَانكِحُوا مَا طَابَ لَكُم مِّنَ النِّسَاءِ مَثْنَىٰ وَثُلَاثَ وَرُبَاعَ\"\n◇وعلماء تانيين قالوا إنه شرط صحيح وجائز لأن الزوج هو إللي تنازل عن حقه ابتداءا ووافق على الشرط وربنا بيقول:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ\"\nوده مذهب الإمام أحمد بن حنبل.\nولو حصل إن الزوج خالف الشرط ده مش معناه إن الزوجة تبقى طالق على طول كده،\nلأ، هي يبقى لها الحق ساعتها في فسخ الزواج، فإما أن تفسخ الزواج، أو إنها تتنازل عن الشرط وترضى بما فعل الزوج، وتبقى زوجة له،\nإلا لو كان الشرط يقول لو تزوجت مرة أخرى فهي طالق، هنا يقع الطلاق\n☆أنا شخصيا بميل للرأي الأول وهو إن الشرط ده فاسد لا يصح، مش متخيلة بصراحة إزاي ممكن أقابل ربنا وأنا كنت سبب في تعطيل شرعه، وتعديت على شيء هو سبحانه أباحه\nوخصوصا يعني إن محدش من الصحابة عمل كده، \nوالموقف بتاع السيدة فاطمة إن رسول الله ﷺ اشترط إن علي يطلقها لو عايز يتزوج بنت أبي جهل فهو موقف له أسبابه زي ما قلنا وهو موقف خاص بفاطمة رضي الله عنها،\nفلو كان ده أمر جائز ومشهور كان زماننا شوفنا قصص كتير زي كده بين الصحابة وخصوصا مع انتشار التعدد في زمن الصحابة\nطبعا ده رأيي الشخصي لا أُلزم بيه أحد\n☆آخر سؤال بقى:\nهل يجوز للأب إنه يمنع زوج ابنته من التعدد بحجة إن دي حاجة تؤذي ابنته وبالتالي تؤذيه زي ما حصل مع رسول الله ﷺ \nلأ، لا يجوز؛ لأن أذى رسول الله ﷺ محرم وكبيرة من الكبائر زي ما قلنا، بعكس باقي البشر مكانتهم مختلفة عن مكانة رسول الله ﷺ وكذلك فاطمة غير النساء بوضعها إللي احنا شرحناه ده\nوبكده انتهت قصة منع رسول الله ﷺ لعلي من إنه يتزوج من بنت أبي جهل.\n☆ملحوظة هاااامة\nالكلام إللي أنا قلته عن التعدد والأحكام الشرعية دي أحكام عاااامة، مفيش حد ياخد الكلام على نفسه أو حد يعرفه ويعمل عليه خناقة\nكل حالة على أرض الواقع لها وضعها وحكمها المختلف، وخصوصا يعني إن مش كل الرجال يصلحوا للتعدد\nفي نماذج سيئة جدا وهم الأعم الأغلب للأسف وبرده في نماذج جيدة وبتتقي الله،\nفأنا هنا مش بناقش قضية التعدد خالص ولا بحاول أحل مشكلة الشرق الأوسط\nكل ما هنالك إني بشرح موقف حصل مع رسول الله ﷺ وبشرح كلام العلماء، يعني أنا مجرد ناقلة عنهم\nيارب تكون وجهة نظري واضحة\nالمصادر في التعليقات\nإن شاء الله المرة الجاية هنبدأ نتكلم عن الوفود إللي جاءت تعلن إسلامها بين يدي رسول الله ﷺ"}, {"n": 232, "l": "الجزء 206 | موت عبدالله بن أبي بن  سلول", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وستة\n#أحداث_السنة_التاسعة_من_الهجرة\n#موت_عبد_الله_بن_أُبيّ_بن_سلول\nهنكمل الكلام النهاردة إن شاء الله عن باقي الأحداث إللي حصلت في السنة التاسعة من الهجرة،\nلكن قبل ما نتكلم عن الأحداث دي في سؤال اتكرر عن الجزء إللي فات،\nفاحنا  هنرد عليه الأول عشان الكل يستفيد،\nالسؤال بيقول:\nهل رسول الله ﷺ كان هيوافق إن علي يتزوج امرأة أخرى مادام هي مش بنت أبي جهل؟\nولّا رسول الله ﷺ معترض أصلا إن علي رضي الله عنه يتزوج من أي امرأة على فاطمة، يعني رسول الله ﷺ رافض إن علي يتزوج على بنته أيا كان هي مين\nشوفوا،\nلو كان علي تزوج امرأة تانية غير بنت أبي جهل مكنش رسول الله ﷺ هيعترض نهائي؛ لأن ده ظاهر الحديث،\nرسول الله ﷺ بيقول:\n\"وإني لستُ أُحرّمُ حلالاُ، ولكن وَاللَّهِ لَا تَجْتَمِعُ بِنْتُ رَسُولِ اللَّهِ وَبِنْتُ عَدُوِّ اللَّهِ عِنْدَ رَجُلٍ وَاحِدٍ أَبَدًا\"\nيعني رسول الله ﷺ معندوش أي مانع إن علي يتزوج بأي امرأة أخرى ما عدا ابنة أبي جهل،\nفهو ﷺ لا يحرم حلال، يعني موافق إن علي يتزوج زوجة تانية عادي، لكن مش بنت أبي جهل\nفي قول تاني بقى بيقول إن عدم الزواج بأخرى دي حاجة خاصة ببنات رسول الله ﷺ،\nيعني مينفعش حد من أزواج بنات رسول الله ﷺ يتزوج عليهن،\nوالكلام ده معلهوش أي دليل، الدليل الظاهر الواضح من كلام رسول الله ﷺ إنه معندوش أي اعتراض على زواج علي من امرأة تانية ماعدا ابنة أبي جهل عشان الأسباب إللي قلناها المرة إللي فاتت\nنرجع بقى للكلام عن الأحداث في السنة التاسعة من الهجرة،\nبعد غزوة تبوك،\nفي السنة التاسعة في شهر رمضان مات النجاشي أَصْحمة،\nقال رسول الله ﷺ:\n\"مَاتَ الْيَوْمَ رَجُلٌ صَالِحٌ فَقُومُوا فَصَلُّوا عَلَى أَخِيكُمْ أَصْحَمَةَ\"\nواحنا اتكلمنا عن النجاشي قبل كده وشوفنا إزاي كان بيساعد المسلمين وعرفنا قصة إسلامه وشوفنا إزاي إن عمرو بن العاص رضي الله عنه أسلم على يده،\nفلما مات النجاشي جاء جبريل وأخبر رسول الله ﷺ عن موته، فجمع رسول الله ﷺ الصحابة وأخبرهم عن موته وصلوا عليه صلاة الغائب لأن مكنش في حد هناك في الحبشة يصلي عليه، رحمه الله ورضي الله عنه.\nمين كمان مات في السنة التاسعة من الهجرة بعد غزوة تبوك؟\nرأس المنافقين عبد الله بن أبي بن سلول\nوموت عبد الله بن أبي بن سلول هو ضربة قاصمة للمنافقين في المدينة،\nوخصوصا بعد فضحهم في غزوة تبوك وحرق مسجد الضرار إللي كانوا بنوه،\nوطبعا احنا مش ناسيين تاريخ ابن سلول الأسود على مدار تسع سنين من ساعة ما رسول الله ﷺ دخل المدينة،\nوانسحابه في غزوة أحد وتعديه على عرض رسول الله ﷺ،\nوغيرها وغيرها من الأحداث،\nلكن لكل شيء نهاية، جاءت لحظة الموت إللي محدش هيهرب منها ومفيش حاجة هتنفع الإنسان ساعتها غير إيمانه بالله\nعبد الله بن أبي بن سلول مرض قبل موته، وقعد في المرض عشرين يوم، وكان ده في شهر شوال،\nالعجيب بقى إن رسول الله ﷺ خلال فترة مرض عبد الله بن أبي بن سلول كان بيروح يزوره بالرغم الكوارث إللي ابن سلول عملها\nوزيارة رسول الله ﷺ لعبد الله بن أبي بن سلول كان لها أهداف هي:\n◇أولا:\nإن رسول الله ﷺ ما زال يرجو إسلام عبد الله بن أُبي بن سلول،\nيعني هو معاه لآخر لحظة يمكن ربنا يهديه،\nواحنا عارفين أد إيه رسول الله ﷺ كان حريص جدا على هداية الناس مهما بلغ أذاهم له ﷺ،\nوالقلوب بين أصابع الله يقلبها كيف يشاء، واحنا شوفنا قبل كده الغلام اليهودي إللي أسلم وهو في مرض الموت،\nفرسول الله ﷺ متمسك بآخر أمل لعله يكون سبب في نجاة ابن سلول من النار.\n☆وهنا رسول الله ﷺ بيضرب لنا أروع الأمثال في الدعوة، وإننا نكون حريصين على نجاة الناس من النار مهما عملوا،\nورسول الله ﷺ لم يُظهر التشفّي لعبد الله بن أبي بن سلول مع إن الموقف ده يريح القلوب لأن ابن سلول أخيرا هياخد جزاؤه بعد إللي عمله ده كله،\nلكن الهدف والغاية مكنتش الانتقام والتشفي أد ماهي كانت محاولة لهداية الإنسان ده وإنقاذه من النار\n¤طبعا يا جماعة ده لا يتعارض مع الفرح بهلاك الظالمين والكفرة الفجرة المحاربين لله ورسوله،\nدي حاجة ودي حاجة، احنا بنبقى حريصين على هداية الناس لأقصى درجة زي رسول الله ﷺ كده، لكن لو ماتوا على ظلمهم وطغيانهم وكفرهم بنفرح طبعا إن ربنا خلصنا منهم ومن شرهم\n◇الهدف الثاني لزيارة رسول الله ﷺ لعبد الله بن أبي بن سلول:\nإن رسول الله ﷺ كان عايز يتألف قلوب قومه؛ فعبد الله بن أُبيّ زعيم من زعماء الخزرج، وأتباعه وأحبابه وإللي بيستمعوا لرأيه كثير،\nفممكن يتأثروا تأثير إيجابي لما يشوفوا رسول الله ﷺ بيزوره وبيعامله بالرفق والحسنى، على الرغم من الأذى إللي ابن سلول سبّبه لرسول الله ﷺ والكل كان عارفه\n◇الهدف الثالث:\nرسول الله ﷺ كان عايز يرفع من قيمة عبد الله بن عبد الله بن أُبي بن سلول، وهو من سادات وفضلاء الصحابة، ومن الصحابة إللي أثبتوا إخلاصهم وتجردهم لله ومن إللي ساهموا بشكل إيجابي في نصرة الإسلام وفي خدمة الدولة الإسلامية، \nو رسول الله ﷺ مكنش عايز إنه يُسبّ أو يُعير بتاريخ نفاق أبوه\nتخيلوا كده يا جماعة موقف عبد الله لما يكون قاعد مع الصحابة وهو بيسمع عن الأزمات المتكررة إللي بتحصل للمسلمين ويعرف إن السبب فيها أبوه وهو مش قادر يعمل حاجة وهو كمان كان من أبر الناس بأبوه،\nفموقفه كان صعب جدا رضي الله عنه\nفكان من رحمة رسول الله ﷺ وعطفه إنه يزوره عشان يخفف الأزمة على عبد الله بن عبد الله بن أبي بن سلول\nجاء اليوم الأخير في حياة عبد الله بن أبي بن سلول فدخل عليه رسول الله ﷺ يزوره كالعادة وهو حزين لاقتراب موته وهو لسه على نفاقه، فقال له رسول الله ﷺ: \n\"قَدْ نَهَيْتُكَ عَنْ حُبِّ يَهُودَ\" وفي رواية تانية قال : أهلكَكَ حب يهود\"\nفقال عبد الله بن أُبي في سوء أدب واضح وفي عناد إلى آخر لحظة:\nقد أبغضهم أسعد بن زُرارة، فما نفعه\nيعني أسعد بن زُرارة كان بيكره اليهود نفعه بإيه كرهه لهم، ماهو مات هو كمان.\n☆ولو تفتكروا أسعد ده إللي بايع بيعة العقبة الأولى الثانية وكان نقيب من النقباء الاثنا عشر وكان بيأخذ مصعب بن عمير ويطوف به على الناس ويدعوهم للإسلام، وهو ابن خالة سعد بن معاذ،\nوهو كان أول واحد جمع المسلمين في بيته لصلاة الجمعة،\nوكان مات بعد الهجرة بأربعة أشهر.\nفعبد الله بن أُبيّ بن سلول لحد آخر لحظة على عناده وتكبره، وبعدين قال لرسول الله ﷺ:\n\"يا رسول الله، ليس هذا بحين عتاب، هو الموت!\nفإن مت فاحضر غسلي، وأعطني قميصك الذي يَلِي جلدك فكفني فيه، وصل علي، واستغفر لي\"\nيعني يارسول خلاص مفيش وقت للعتاب أنا خلاص بموت، فلما أنا أموت احضر الغسل بتاعي وكفني في القميص بتاعك الملامس لجلدك، وصلي عليّ واستغفر لي.\nواحنا ممكن نستغرب طلب ابن سلول، يعني إيه إللي يخليه يطلب حاجة زي كده من رسول الله ﷺ \nهل فجأة اكتشف الحقيقة وبقى عايز يتوب عن إللي عمله في حياته؟\nولّا كان طمعان إنه مع نفاقه ده لما رسول الله ﷺ يحضر غسله ويكفّنه في قميصه ربنا هيخفف عنه ويدخله الجنة وينجيه من النار؟\nولّا مكنش عايز ابنه يتعيّر بيه بعد موته فعايز قميص رسول الله ﷺ يبقى فخر له؟\nالله أعلم كانت نيته إيه لما طلب الطلبات دي من رسول الله ﷺ، منعرفش بالضبط هو كان بيفكر في إيه ساعتها\nالمهم إن رسول الله ﷺ استجاب لطلبه ورجع بيته عشان يقلع الثوب المباشر لجلده ﷺ، \nفجاء عبد الله بن عبد الله بن أبي بن سلول يطلب القميص من رسول الله ﷺ عشان يكفنوا فيه أبوه وكان ساعتها مات خلاص،\nفرسول الله ﷺ أعطى قميصه لعبد الله عشان يكفنوه فيه، وكان رسول الله ﷺ من طبعه إنه لا يرد أي حد يسأله أو يطلب منه حاجة،\nورسول الله ﷺ كان له هدف تاني من إعطاء ابن سلول القميص بتاعه، قال ﷺ:\n\"إِنَّ قَمِيصِي لاَ يُغْنِي عَنْهُ مِنَ اللَّهِ شَيْئًا، وَإِنِّي لأَرْجُو أَنْ يُسْلِم بِفِعْلِي هَذَا أَلْفَ رَجُلٍ مِنْ قَوْمِهِ\"\nيعني رسول الله ﷺ بيقول إن قميصه مش هينفع ابن سلول بشيء، لكنه ﷺ يطمع أو يتمنى إن بسبب إللي عمله مع ابن سلول ده إن ألف رجل من قوم ابن سلول يؤمن برسول الله ﷺ،\nوفعلا ده إللي حصل، بعد الحادثة دي أسلم وتاب ألف رجل من الخزرج\nجاء وقت الصلاة على ابن سلول، عمر رضي الله عنه لما شاف إن رسول الله ﷺ هيصلي عليه راح قايم وقف أمام رسول الله ﷺ وأَخَذَ بِثَوْبِ رَسُولِ اللهِ ﷺ، وقال:\nيا رسولَ اللهِ أتُصلِّي علَى عدوِّ اللهِ ابنِ أبيٍّ بنُ سلولَ، وقد قالَ يومَ كذا كذا وَكَذا \nيعني يا رسول الله إزاي هتصلي على ابن سلول المنافق عدو الله وهو إللي عمل كذا وكذا، وقعد عمر يفكره بالكوارث إللي ابن سلول عملها،\nوكمّل عمر كلامه وقال:\n\"أليسَ قَد نهاكَ اللهُ أن تصلِّيَ علَى المنافقينَ فقال:\n استغفِرِ اللهَ لَهُم، أو لا تستغفِرْ لهُم، إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ\"\nفرسول الله ﷺ تبسم لعمر وقال له: \nأخِّر عنِّي يا عمرُ!\nيعني ابعد يا عمر خليني أصلي عليه،\nفأصر عمر على كلامه وقعد يجادل رسول الله ﷺ، فلما أكثر من الكلام رسول الله ﷺ قال له:\n\"إنِّي خُيِّرتُ فاختَرتُ،\n قد قيل لي اسْتَغْفِرْ لَهُمْ أَوْ لَا تَسْتَغْفِرْ لَهُمْ إِنْ تَسْتَغْفِرْ لَهُمْ سَبْعِينَ مَرَّةً فَلَنْ يَغْفِرَ اللَّهُ لَهُمْ لَو أعلمُ أنِّي إن زدتُ علَى السَّبعينَ غُفِرَ لهُ لَزِدْتُ عليها\"\nيعني رسول الله ﷺ بيقول لعمر إن ربنا خيّره بين إنه يستغفر لهم أو لا يستغفر لهم، ورسول الله ﷺ اختار إنه يستغفر لهم ولو يعرف إنه لو زاد عن السبعين ربنا هيغفر له فهيزيد الاستغفار عن سبعين مرة، وهيفضل يستغفر لهم مادام ربنا لم ينهاه عن الاستغفار لهم،\nفعمر قال لرسول الله ﷺ:\nإِنَّهُ مُنَافِقٌ!!\nفرسول الله ﷺ صلى على ابن سلول بالرغم من اعتراض عمر،\nفبعد دفن ابن سلول بوقت بسيط نزلت الآية:\n\"وَلَا تُصَلِّ عَلَىٰ أَحَدٍ مِّنْهُم مَّاتَ أَبَدًا وَلَا تَقُمْ عَلَىٰ قَبْرِهِ ۖ إِنَّهُمْ كَفَرُوا بِاللَّهِ وَرَسُولِهِ وَمَاتُوا وَهُمْ فَاسِقُونَ\"\nيعني ربنا بيقول لرسول الله ﷺ متصليش على أي حد من المنافقين مات ولا تقف عند القبر بتاعه وتحضر دفنه؛ لأنهم غير مسلمين وكفروا بالله ورسوله وماتوا على الكفر ده\nفلم يُصلِّ رسول الله ﷺ على أي منافق بعد كده أبدا ولم يَقم على قبره حتى مات ﷺ.\n☆السؤال هنا بقى\nإزاي عمر بن الخطاب رضي الله عنه عرف إن ربنا نهى رسول الله ﷺ إنه يصلي على المنافقين والآية مكنتش لسه نزلت\nحاجة من اتنين:\nإما إنه يكون وقع له في خاطره النهي عن الصلاة على ابن سلول ويكون ده من باب الإلهام زي ما حصل قبل كده في الأمور إللي وافق فيها عمر ربنا في حكم شرعي زي نزول آية الحجاب وزي الحكم على أسرى بدر،\nأو إنه فهم واستنبط الحكم من خلال آية:\nاستغفر لهم أو لا تستغفر لهم.\nالمهم بقى إن بعد الأحداث دي عمر بيقول عن نفسه:\n\"فعَجِبْتُ بعدُ مِن جُرأتي علَى رسولِ اللهِ ﷺ يومئذٍ، واللهُ ورسولُهُ أعلَمُ\"\nيعني عمر بيقول إنه استغرب من جرأته على رسول الله ﷺ وإنه كان عايز يمنعه بالقوة مع إن هو مكنش يعرف الحكم والله ورسوله أعلم منه في القضية دي\nمن خلال قصة موت ابن سلول نقدر نشوف إللي كان عليه رسول الله ﷺ من الصَّفح والعفو عن أي حد يظهر الإسلام حتى ولو كان باطنُه على خلافِ ذلك\nوده يعرفنا السبب إللي خلى رسول الله ﷺ يصمم إنه يصلي على ابن سلول، وهو إنه مكنش مظهر للشرك لكن كان ظاهره الإسلام، فكان لازم يصلي عليه\nورسول الله ﷺ كان قال:\n\"إِنِّي لَمْ أُومَرْ أَنْ أَنْقُبَ عَنْ قُلُوبِ النَّاسِ، وَلا أَشُقَّ بُطُونَهُمْ\"\nيعني مش مطلوب مني أشوف إللي في قلوب الناس وأعرف هم مخبيين إيه، مليش منهم غير الظاهر\nبعد موت عبد الله بن أبي بن سلول انحسرت حركة النفاق والمنافقين في المدينة،\nوبعد غزوة تبوك وانتصار المسلمين فيها كان العرب في كل الجزيرة العربية بيراقبوا الأحداث، \nوعرفوا إنهم ملهمش طاقة أبداً بحرب المسلمين،\nعشان كده بعد عودة رسول الله ﷺمن تبوك تقدروا تقولوا إن القبائل العربية أخذت قرار شبه جماعي بالقدوم إلى المدينة للتواصل مع رسول الله ﷺ، \nفجاءت بعض القبائل لتعلن إسلامها وهي مقتنعة ومرحبة بيه،\nوقبائل تانية جاءت تسلم عشان خايفين من الإسلام وقوة الدولة الإسلامية إللي حتى جيوش الدولة الرومانية خافوا منها\nوفي قبائل جاءت تتفاوض مع رسول الله ﷺ، وفي إللي جاء عشان يعمل معاهدة مع رسول الله ﷺ ويستمر على دينه،\nواحنا كنا قلنا قبل كده إن العام التاسع للهجرة جاءت فيه وفود كثيرة عشان كده اتسمى العام ده بعام الوفود،\nكان عدد إللي جاءت على الأقل ستين وفداً، ووصل عدد الوفود في بعض التقديرات إلى أكثر من مائة وفد،\nفاحنا هنتكلم عن أهم الوفود بصفة عامة إن شاء الله\nأهم الوفود إللي جاءت بعد غزوة تبوك هو وفد ثقيف، فاكرين ثقيف إللي كانت متحصنة بالطائف وكان رسول الله ﷺ أرسل لهم مالك بن عوف يحاصرهم وكانوا قتلوا زعيمهم عروة بن مسعود الثقفي\nأهم دلوقتي جايين يعلنوا إسلامهم عند رسول الله ﷺ،\nإيه إللي خلاهم يغيروا وجهة نظرهم؟\nوإيه الحوار إللي دار بينهم وبين رسول الله ﷺ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 233, "l": "الجزء 207 | اسلام ثقيف وهدم الربه أو اللات", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وسبعة\n#أحداث_السنة_التاسعة_من_الهجرة\n#إسلام_ثقيف_وهدم_الرّبّة_أو_اللّات\nوقفنا المرة إللي فاتت عند مجيء وفد ثقيف للمدينة عشان يعلنوا إسلامهم،\nلكن ثقيف مكنوش عايزين يدخلوا في الإسلام عشان مقتنعين بيه أو حابينه مثلا\nوضعهم وأحوالهم همّ إللي اضطروهم للدخول في الإسلام\n☆إيه إللي حصل معاهم بقى واضطرهم للدخول في الإسلام\n◇أولاً:\nمعظم القبائل العربية الكبرى دخلوا في الإسلام، ومن القبائل دي فرع عَيْلان إللي كان بينتمى له أهم ثلاثة قبائل:\n《غَطَفَان، وبنو سُلَيم، وهوازن》\nواحنا اتكلمنا عن التقسيمة دي بالتفصيل في الجزء المائة وواحد وسبعون،\nفمتبقّاش من هوازن غير فرع ثقيف هو إللي لسه مدخلش في الإسلام،\nوكده ثقيف بقت لوحدها وهي معندهاش القدرة على حرب وقتال كل قبائل العرب\n◇ثانياً:\n مالك بن عوف كان محاصر الطائف هو وقبيلته هوازن بعد ما أسلموا فبقى في تضييق عليهم جامد، وطبعا ده أدى للسبب الثالث وهو:\n◇سوء الأحوال الاقتصادية في الطائف بسبب الحصار وفقدت الطائف مكانتها التجارية؛ لأنها بقت مكان غير آمن، ولا يطمئن إليه عامة تجار العرب.\n◇رابعاً:\n فقدت ثقيف أحد زعمائها المعدودين وهو عروة بن مسعود الثقفي، ومش بعيد إنها تفقد رجالها واحد ورا التاني.\nفقررت ثقيف إنهم يرسلوا وفد إلى رسول الله ﷺ مكون من ستة أشخاص، وفي رواية كانوا أكثر من عشرة، عشان يعلنوا إسلامهم وإسلام ثقيف بين يدي رسول الله ﷺ، \nكان مين بقى على رأس الوفد ده\nعبد يَالِيل، فاكرينه\nإللي كان استهزأ برسول الله ﷺ لما رسول الله ﷺ راح للطائف وقاله:\nده أنا أقطع أستار الكعبة لو ربنا أرسلك، واحنا اتكلمنا عن الموضوع بالتفصيل في الجزء الثامن والعشرين،\nدلوقتي بقى هو جاي بعد السنين دي كووولها عشان يسلم\nشوفتوا الأوضاع بتتبدل إزاي ومفيش حاجة بتفضل على حالها\nهل عبد ياليل كان يتصور في يوم من الأيام إن محمد ﷺ إللي أظهر له العداء وسخر منه هييجي عليه اليوم ويبقى هو الزعيم وعبد ياليل نفسه يكون تابع له\n\"إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ\"\nجاء الوفد ودخلوا على رسول الله ﷺ فاستقبلهم رسول الله ﷺ استقبال طيب يليق به كنبي، وعمل لهم خيمة في المسجد عشان يشوفوا أحوال المسلمين ويتعلموا من خطب رسول الله ﷺ،\nولم يُذكّرهم رسول الله ﷺ أبدا باللي عملوه معاه لما راح يدعو في الطائف قبل الهجرة للمدينة،\nلما قعدوا مع رسول الله ﷺ عشان يُسلموا اشترطوا عليه شروط، قالوا لرسول الله ﷺ:\nاحنا هندخل في الإسلام يا رسول الله بس بشرط إنك تأذن لنا في الزنا؛ لأن احنا بنسافر أماكن بعيدة وبنبعد عن أهلنا، فلابد لنا من الزنا\nفقال لهم رسول الله ﷺ:\nهو عليكم حرام\nإن الله عز وجل يقول:\n\"وَلا تَقْرَبُوا الزِّنَى إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا\"\nيعني رسول الله ﷺ بيقول لهم ده حد من حدود الله ولا يمكن أبداً التنازل عنه،\nمع إن إسلام ثقيف هيبقى إضافة كبيرة جدا للدولة الإسلامية، ورسول الله ﷺ كان ممكن في البداية بس يقولهم ادخلوا وبعدين نبقى نشوف الموضوع بعدين،\nلكن رسول الله ﷺ من البداية كده بيوضح لهم إن هي دي شريعة الإسلام عاجبكم على كده أهلا وسهلا مش عاجبكم انتم حرين، احنا مش بنفصّل الدين على مزاج الناس وأهواؤهم\nده دين، لا يجوز إننا نفرط حتى في أمر واحد من أوامر ربنا\nفلقوا رسول الله ﷺ مصمم ومفيش أي مجال يقنعوه، فدخلوا في الشرط التاني، قالوا له:\nأفرأيت الربا؛ فإنه أموالنا كلها؟\nيعني احنا أموالنا كلها من الربا مش هينفع تقولنا الربا حرام ومتتعاملوش بالربا، فانت تخلي لنا الربا حلال.\n قال لهم رسول الله ﷺ : \nلكم رؤوس أموالكم، فإن الله تعالى يقول:\n \"يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِنْ كُنتُمْ مُؤْمِنِينَ\"\nيعني تاخدوا رأس المال بس إللي بدأتوا بيه الربا، أما أي زيادة عليه فهي محرمة، لازم تتخلصوا منها،\nفقال زعيمهم عبد ياليل:\nأفرأيت الخمر؛ فإنه عصير أرضنا لا بد لنا منه؟\nيعني الخمر بقى مفيش فيها مجال ولازم نشربها، ده احنا إللي بننتجها،\nطبعا واضح إنهم مش عايزين يسلموا رغبة في الإسلام لكن الظروف هي إللي دفعتهم لكده\nقال رسول الله ﷺ:\nإن الله قد حرمها. وقرأ عليهم:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّمَا الْخَمْرُ وَالْمَيْسِرُ وَالأَنصَابُ وَالأَزْلامُ رِجْسٌ مِنْ عَمَلِ الشَّيْطَانِ فَاجْتَنِبُوهُ لَعَلَّكُمْ تُفْلِحُونَ\"\nحاول وفد ثقيف إنهم يقنعوا رسول الله ﷺ إنه يحذف لهم الثلاثة أمور دي من الإسلام لكن رسول الله ﷺ كان واضح تمام الوضوح، وكان حازماً تمام الحزم، \nمفيش مساومة في الدين، ولا إننا نلتقي في منتصف الطريق إذا كان الأمر يخص العقيدة والحلال والحرام،\nولم يسعَ إلى تأليف قلوبهم عن طريق حذف أو تبديل في الشريعة زي ما للأسف ناس كتير بتعمل دلوقتي بحجة تأليف القلوب وتحبيب غير المسلمين في الإسلام\nمش ده منهج رسول الله ﷺ أبدا\nالمهم،\nوفد ثقيف قاموا قعدوا مع بعض عشان يتشاوروا ويشوفوا هيعملوا إيه، فقال بعضهم لبعض: \nنخاف إنْ خالفناهُ؛ يومًا كيوم مكة، انطلقوا فأعطوه ما سأل وأجيبوه\nيعني خايفين يرفضوا الإسلام كامل بدون حذف ولا تبديل، فييجي يوم رسول الله ﷺ يغزوهم؛ ويحصل لهم زي ما حصل في مكة،\nفشافوا إن أحسن حل إنهم يسمعوا كلام رسول الله ﷺ،\nفراحوا لرسول الله ﷺ مرة تانية وقالوا له إنهم موافقين يدخلوا في الإسلام زي ما رسول الله ﷺ عايز،\nلكن لسه عندهم مشكلة\nقالوا لرسول الله ﷺ:\nأريت الرّبّة ماذا نصنع فيها؟ \nالربة دي هي اللّات وهي الصنم المعبود في الطائف، وكانت من أعظم أصنام العرب، والجميع كان يقسم بها ويهدي إليها ويذبح عندها ويؤمن بها،\nفأجاب عليهم رسول الله ﷺ إجابة حاسمة لا مُجاملة فيها، قال: اهدموها\nففزع وفد ثقيف وقالوا: \nهيهات لو تعلم الربة أنك تريد هدمها لقتلت أهلنا\nيعني انت بتقول اهدموها كده بكل سهولة، دي لو عرفت إنك عايز تهدمها هتقتل أهلنا،\nفمين كان حاضر المفاوضات دي ومقدرش يمسك نفسه\nعمر بن الخطاب رضي الله عنه\nقال عمر لعبد ياليل:\nويْحك يا عبد ياليل إن الرّبة حجر لا يدري مَن عبده مِمّن لا يعبده\nفرد عليه عبد ياليل وقال: إنّا لم نأتِكَ يا عمر\nيعني ملكش دعوة احنا مش جايين نتكلم معاك انت،\nلكن رسول الله ﷺ أصر على هدم صنم اللات، أو الربة،\nفلما لقوا إن مفيش مفر من هدمها بدأوا يساوموا رسول الله ﷺ على توقيت هدمها،\nيعني قالوا لرسول الله ﷺ إنه يترك لهم صنم اللات ثلاث سنوات قبل ما يهدمها، \nفرفض رسول الله ﷺ، فقالوا طب خليها سنتين، فرفض رسول الله ﷺ، طب خليها سنة...طب خليها شهر...وكل ده ورسول الله ﷺ بيرفض وصابر عليهم للآخر\nفلما لقوا مفيش مفر قالوا له في يأس:\n تولى أنت هدمها، أما نحن لا نهدمها أبداً\nيعني انت عايز تهدمها اهدمها، لكن احنا مش هنهدمها\nدي حاجة سهلة ومفيهاش مشكلة فوافق رسول الله ﷺ على طلبهم وقال لهم:\nفسأبعثُ إليكم من يكفيكُم هدمها\nقبل ما يقوموا طلبوا طلب أخير من رسول الله ﷺ وهو إنه يعفيهم من الصلاة\nعايزين يدخلوا الإسلام بس ميصلوش،\nطبعا ده رد فعل طبيعي لناس عاشت سنين طويلة جدا بتعبد الأصنام وماشيين بأهواؤهم، كل واحد يعمل إللي عايزه، ومش فاهمين يعني إيه إسلام واستسلام لأوامر الله وإن الإنسان عبد لله يجب عليه إنه يطيع ربنا كما أمره،\nمش يقعد ينقّي من الدين إللي يعجبه ويسيب إللي ميعجبوش،\nفهم مفكرين بقى إن تشريعات الإسلام هتبقى زي تشريعات الكهنة إللي كانوا بيخدموا الأصنام،\nمكنوش لسه فاهمين إن الدين الصحيح هو كما قال الله تعالى:\n\"قُلْ إِنَّ صَلاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ\"\nكل صغيرة وكبيرة في حياتنا بيحكمها الإسلام وبيتدخل فيها وبيحركها\nفطبعا رسول الله ﷺ رفض طلبهم، إزاي يعني دين من غير صلاة\nفوافق وفد ثقيف على الدخول في الإسلام أخيرا بدون أي شروط\nكان وفد ثقيف قاعدين في الخيمة إللي رسول الله ﷺ عملها لهم في المسجد، وبين الحين والآخر كانوا بيرجعوا لرحالهم إللي تركوها خارج المدينة مع شاب اسمه عثمان بن أبي العاص،\nوكان هو أصغر واحد فيهم، كان عمره أقل من عشرين سنة،\nفكان لما أصحابه بيرجعوا للرّحال كان هو بيروح لرسول الله ﷺ في المدينة عشان يتعلم منه،\nولو لقى رسول الله ﷺ نايم كان يروح لأبي بكر يتعلم منه،\nفأُعجب به رسول الله ﷺ وبصدقه وإخلاصه وشاف فيه خير كثير،\nفجعله رسول الله ﷺ أمير على الطائف\nيعني رسول الله ﷺ عزل عبد ياليل إللي كان من خلال مفاوضاته مع رسول الله ﷺ كان واضح إنه مش مقتنع بالإسلام وعيّن بداله الشاب المجتهد المخلص عثمان بن أبي العاص،\nوكان رسول الله ﷺ شاف فيه ذكاء وكفاءة في القيادية، وكمان هو لسه شاب ففطرته لم تتلوث بالشركيات إللي عاش عليها عبد ياليل سنين طويلة، وممكن ينحرف بثقيف عن المعنى الحقيقي للإسلام،\nولو تفتكروا، ده نفس إللي رسول الله ﷺ عمله في مكة، عزل أبا سفيان عن حكم مكة وعيّن بداله عتّاب بن أُسيد،\nوكمان رسول الله ﷺ تعامل مع أهل ثقيف زي ما تعامل مع أهل مكة؛ عفا عنهم أجمعين برغم التاريخ السيء إللي مر به رسول الله ﷺ والمسلمون مع الطائف، \nوبكده رسول الله ﷺ بيثبت لنا إن منهج العفو هو منهج أصيل في الإسلام، ومكنش مجرد حدث عابر خاص بأهل مكة\nرجع وفد ثقيف إلى الطائف، وبعد محاورات وجدال مع ثقيف قبلت ثقيف بالإسلام أخيرا\nوبعدها بوقت بسيط جاءت السّريّة الإسلامية المُكلّفة بهدم صنم اللات،\nوكان على رأس السرية ثلاثة من أبطال المسلمين، كل واحد منهم له دلالة خاصة جداً\nيعني رسول الله ﷺ اختار الثلاثة دول بالذات دونًا عن باقي الصحابة لأسباب معينة،\n◇البطل الأول:\nخالد بن الوليد رضي الله عنه، سيف الله المسلول ومن أعظم قادة الجيش الإسلامي،\nوالسبب في اختيار خالد رضي الله عنه إن مهمة دخول الطائف وهدم اللات مهمة خطيرة جدا،\nعشان كده عايزين رجل كُفء متميز وخبير بالخطط والمناورات العسكرية\n◇البطل الثاني: \nالمُغيرة بن شعبة الثقفي إللي كان واقف حارس لرسول الله ﷺ في صلح الحديبية،\nوسبب اختيار رسول الله ﷺ للمغيرة هو إنه من ثقيف وأهل الطائف أدرى بشعابها،\nوكمان القبيلة أو البطن إللي ينتمي لها المغيرة هيقفوا حراس يحرسوا المسلمين وهم بيهدموا صنم اللات، وبكده محدش هيتهور ويقتل المغيرة زي ما حصل مع عمه عروة بن مسعود الثقفي، فهي كلها أخذ بالأسباب؛\nلأن احنا لسه مش متأكدين من ثبات أهل الطائف على الإسلام، ومش عايزين نعرض أي واحد من المسلمين لخطر ملوش لازمة\n◇البطل الثالث:\n أبو سفيان بن حرب رضي الله عنه، وكان قد حَسُن إسلامه بعد غزوة حنين وبقى قوة أدبية وسياسية كبيرة جداً في الدولة الإسلامية، \nوسبب اختيار رسول الله ﷺ لأبي سفيان إن دي رسالة لكل العرب، يعني شوفوا زعيم الوثنية السابق في الجزيرة العربية جاي بنفسه عشان يهدم صنم الطائف،\nالصنم إللي قعدتم تعبدوه سنين طويلة وتحلفوا بيه وتذبحوا عنده، دلوقتي بيتهدم بيد الرجل إللي كان بيدافع وبيحارب عشانه\nدخلت السرية الطائف، واجتمع أهل الطائف كلهم عشان يشوفوا هيحصل إيه للصنم إللي عبدوه همّ وآباؤهم لسنين وسنين،\nوكان في ناس مفكرين إن الربة (اللات) هتنتقم لنفسها، يعني أول ما يقربوا منها هتحولهم لحجارة مثلا أو تضربهم بصاعقة تحرقهم، كده يعني\nهم لسه لحد دلوقتي عندهم شك في الإسلام ومؤمنين باللات،\nوهي لحظات وسقطت اللات بعد ما كسرها أبطال المسلمين،\nوظهرت لهم الحقيقة الواضحة إللي كانت غايبة عن عيونهم وعن عقولهم وكأن كان في غشاوة على عيونهم واتشالت،\nدخل الإيمان في قلوبهم لما شافوا الإله إللي عبدوه اتكسر من غير حتى ما يدافع نفسه\nأشد أذى تعرض له رسول الله ﷺ طول حياته هو الأذى إللي حصل له من أهل الطائف،\nوكان ساعتها يقدر ينتقم منهم، زي ما عرض عليه مَلك الجبال، لكنه ﷺ صبر عليهم وكان يرجو إسلامهم في يوم من الأيام،\nومرت السنوات وحصل فعلا إسلامهم بعد حوالي اثنا عشرة سنة، فذهب الألم وبقي الأجر\nومش بس كده، ده لما ارتدت جزيرة العرب كلها كانت الطائف من المدن إللي ثبتت على الإسلام،\nوتحققت أمنية رسول الله ﷺ الصادقة:\n\"أرجو أن يُخرج الله عز وجل من أصلابهم من يعبد الله وحده\"\nمش بقولكم:\n\" إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ\"\nوبكده انتهت قصة الوفد الأول إللي جاء لرسول الله ﷺ بعد غزوة تبوك\n♡"}, {"n": 234, "l": "الجزء 208 | وفد ضمام بن ثعلبه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وثمانية\n#أحداث_السنة_التاسعة_من_الهجرة\n#وفد_ضِمَام_بن_ثَعْلبة\nرجعنا بفضل الله للسيرة من تاني، كل عام أنتم بخير وعافية في الدين والدنيا يارب وتقبل الله منا ومنكم صالح الأعمال \nكنا اتكلمنا قبل الانقطاع عن وفد ثقيف إللي جاء وأعلن إسلامه وعرفنا قصتهم كاملة،\nقبل ما نتكلم عن الوفد الثاني من الوفود المهمة إللي جاء لرسول الله ﷺ عايزين نعرف حصل إيه مع وحشي بن حرب،\nلو تفتكروا كنت قلت لكم في الجزء المائة وخمسة وستين إن رسول الله ﷺ أهدر دم مجموعة من الناس وأمر بقتلهم لما دخل مكة في عام الفتح،\nوكان منهم وحشي بن حرب قاتل حمزة، ووحشي ساعتها  كان هرب من مكة إلى الطائف لما عرف إن جيش المسلمين داخل مكة خلاص،\nفلما ثقيف قررت إنها تدخل في الإسلام؛ وحشي لقى نفسه ملوش مكان يلجأ له\nفخرج وحشي مع وفد ثقيف لرسول الله ﷺ عشان يُسلم، \nفلما رآه رسول الله ﷺ قال له:\nآنْتَ وَحْشِيٌّ؟\nفقال وحشي: نَعَمْ.\nفقَالَ رسول الله ﷺ له: أَنْتَ قَتَلْتَ حَمْزَةَ؟\nفقال وحشي:\nقَدْ كَانَ مِنَ الأَمْرِ مَا بَلَغَكَ.\nيعني إللي انت عارفه هو إللي حصل وأنا قتلته فعلا،\nفقَالَ له رسول الله ﷺ:\n فَهَلْ تَسْتَطِيعُ أَنْ تُغَيِّبَ وَجْهَكَ عَنِّي؟\nيعني رسول الله ﷺ مكنش عايز يشوف وحشي؛ لأن كل ما هيشوفه هيفتكر مقتل حمزة ودي حاجة تؤذي رسول الله ﷺ،\nودي مشاعر طبيعية يا جماعة، يعني من الطبيعة البشرية إن الواحد يكره يشوف الشخص إللي آذى قريبه أو آذى حد بيحبه، ومش شرط وقوع الهجرة المنهية بينهما،\nيعني في الموقف ده مفهوش المشاحنة ولا الخصام ولا الهجر إللي ربنا نهى عنه،\nالموضوع وما فيه رسول الله ﷺ بيتجنب إنه يشوف وحشي، لكن لو شافه أو جاء يسأله عن شيء أكيد هيرد عليه،\nوخصوصا أصلا إن وحشي رضي الله عنه أسلم، والإسلام يمسح ما قبله، وفي رواية بتقول إن لما وحشي جاء للمدينة الصحابة قالوا لرسول الله ﷺ:\nهذا وحشي!\nيعني الرجل إللي قتل حمزة بقى في إيدنا وممكن نقتله وننتقم لمقتل حمزة، \nلكن رسول الله ﷺ قال لهم:\n\"دعُوه فَلَإِسلام رجلٍ واحدٍ أحبّ إليّ مِن قتْل ألف كافر\"\nيعني المسألة مش مسألة انتقام، هو أسلم، خلاص انتهى الموضوع بقى وربنا مش هيحاسبه عليه\nفلما وحشي سمع رسول الله ﷺ بيطلب منه إنه يتجنبه خرج من عنده وعاش وحشي في المدينة وكان حريص إنه ميخليش رسول الله ﷺ يشوفه، يعني مثلا مكنش يعدي من أمام رسول الله ﷺ ولا حتى عينه تقع عليه، فما رآه حتى مات ﷺ\nوبعد كده وحشي قتل مسيلمة الكذاب زي ما هنشوف بعدين إن شاء الله إذا كان في العمر بقية\nنرجع بقى للكلام عن الوفود، معانا النهاردة وفد تاني مهم، الوفد ده كان وفد غريب عجيب شوية\nالوفد ده مكون من رجل واحد فقط، ومع إنه رجل واحد فقط لكن كان نفعه عظيم جدا،\nحتى عبد الله بن عباس رضي الله عنه بيقول:\nما سمعنا بوافدِ قومٍ كان أفضل من هذا الوافد،\nيعني احنا مسمعناش عن حد أرسله قومه أفضل من الوافد ده\nطيب ليه عبد الله بن عباس قال كده\nشوفوا الأحداث واحكموا بنفسكم\nبنو سعد بن بكر اختاروا واحد منهم عشان يأتي لرسول الله ﷺ ويسألوه عن الإسلام، فاختاروا واحد اسمه:\n 《ضِمَام بن ثَعْلبة》\nوكان ضِمَام رجل حكيم وقوي، فتوجه ضِمَام للمدينة ولما وصل أَنَاخَ بعيرَه، يعني قعّد بعيره على الأرض ونزل من عليه وربط البعير على باب المسجد ودخل للقاء رسول الله ﷺ،\nضِمَام ميعرفش رسول الله ﷺ ولا عمره شافه،\nفدخل المسجد لقى مجموعة رجال قاعدين، مفيش واحد منهم متميّز عن التاني، فسأل ضِمَام كده على طول وش، من غير سلام وكلام:\nأَيكم ابنُ عبد المطلب؟\nيعني هو بيسأل عن رسول الله ﷺ، ورسول الله ﷺ قاعد وسطهم محدش يقدر يميّزه من بينهم لا بملابس ولا بمكان جلوسه، وده من تواضعه ﷺ،\nفقال رسول الله ﷺ:\n\"أَنَا ابْنُ عَبْدِ الْمُطَّلِبِ\"\nفقال ضِمَام:\n\"يَا ابْنَ عَبْدِ الْمُطَّلِبِ، إِنِّي سَائِلُكَ وَمُغْلِظٌ عَلَيْكَ فِي الْمَسْأَلَةِ، فَلَا تَجِدَنَّ فِي نَفْسَكَ\"\nيعني بيقول لرسول الله ﷺ إنه عنده أسئلة عايز يعرف إجابتها، وهو بيتكلم بأسلوب فيه شدة وحِدّة فبيطلب من رسول الله ﷺ إنه ميزعلش منه ومن أسلوبه وكلامه،\nفقال له رسول الله ﷺ: \n\"لاَ أَجِدُ فِي نَفْسِي، سَلْ عَمَّا بَدَا لَكَ\"\nيعني متقلقش اسأل زي مانت عايز مش هزعل،\nفقال ضِمَام: \nأَنْشُدُكَ بِاللَّه إِلَهَكَ وإِلَهِ مَنْ كَانَ قَبْلَكَ وَإِلَهِ مَنْ هُوَ كَائِنٌ بَعْدَك، آللَّه بَعَثَكَ إِلَيْنَا رَسُولًا؟!!\nيعني بيحلّفه بالله ربه ورب كل شيء من قبل رسول الله ﷺ ورب كل شيء من بعد رسول الله ﷺ هل الله فعلا أرسله رسول؟\nوهو بيشدد عليه في القَسَم كده عشان يحفز رسول الله ﷺ إنه يكون صادق معاه،\nزي كده لما واحد بيقول للتاني بالله عليك تقول لي الحقيقة وخليك صادق معايا،\nوكمان فيها تخويف، يعني خد بالك إللي خلق إللي قبلك وإللي هيخلق إللي بعدك مينفعش تكذب عليه\nفرسول الله ﷺ رد عليه بكل هدوء وثقة:\n \"اللَّهُمَّ نَعَمْ\"\nفقال ضِمَام:\nفَأَنْشُدُكَ بِاللَّه إِلَهَكَ، وَإِلَهَ مَنْ كَانَ قَبْلَكَ، وَإِلَهَ مَنْ كَائِنٌ بَعْدَكَ، آللَّه أَمَرَكَ أَنْ نَعْبُدَهُ وَحْدَهُ لاَ نُشْرِكُ بِهِ شَيْئًا، وَأَنْ نَخْلَعَ هَذِهِ الأَوْثَانَ الَّتِي كَانَ آبَاؤُنَا يَعْبُدُونَ؟\nيعني حلّفه مرة تانية بالله هل ربنا إللي أرسله ده أمره إنه يقول للناس إنهم يعبدوه وحده لا شريك له ويتركوا عبادة الأصنام؟\nفقال له رسول الله ﷺ: \"اللَّهُمَّ نَعَمْ\"\n\"ثُمَّ جَعَلَ يَذْكُرُ فَرَائِضَ الإِسْلَامِ فَرِيضَةً فَرِيضَةً، الْصَّلَاةُ وَالْزَّكَاةُ وَالْصِّيَامُ وَالْحَجُّ، وَشَرَائِعُ الْإِسْلَامِ، يَنْشُدُهُ عِنْدَ كُلِّ فَرِيضَةٍ كَمَا نَشَدَهُ فِي الَّتِي كَانَ قَبْلَهَا، حَتَّى فَرِغَ\"\nيعني ضِمَام بن ثَعْلبة قعد يسأل رسول الله ﷺ بالله على كل فرائض الإسلام هل ربنا أمر بيها ولّا لأ،\nوكل مرة رسول الله ﷺ يقول له: اللَّهُمَّ نَعَمْ، لحد ما خلص كل إللي عايز يسأل عليه،\nوفي الآخر قال ضِمَام بن ثَعْلبة:\nإِنِّي أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّه، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّه، وَسَأُؤَدّي هَذِهِ الْفَرَائِضَ، وَأَجْتَنِبَ مَا نَهَيْتَنِي عَنْهُ، لاَ أَزِيْدُ وَلاَ أَنْقُصُ\nومشي من عند رسول الله ﷺ وتوجه لقومه، رسول الله ﷺ بقى قال عنه بعد ما مشي:\n\"إِنْ يَصْدُقْ ذُو العَقِيْصَتَيْنِ يَدْخُلِ الْجَنَّةَ\".\nكان ضِمام عامل شعره ضفيرتين، فرسول الله ﷺ بيقول لو صدق صاحب العَقِيْصَتَيْنِ يعني الضفيرتين في كلامه والتزام باللي قاله ده هيدخل الجنة\nضمام توجّه لبعيره وركبه ورجع لقومه، لما وصل لقومه أول حاجة نطقها وقالها لهم:\nبئستِ اللاتَ والعزَّى\nيعني بيشتم اللات والعزى، فقومه اتصدموا من كلامه وقالوا:\nمَه يا ضمامُ اتقِ البرصَ والجذامَ اتقِ الجنونَ\nيعني إيه إللي انت بتقوله ده يا ضمام، خاف من الآلهة إللي انت بتشتمها دي أحسن تصيبك بالبرص والجُزام أو الجنون،\nفقال لهم ضِمَام بن ثَعْلبة:\nويلَكم! إنهما واللهِ ما يضرانِ ولا ينفعانِ\nإن اللهَ قد بعث رسولًا وأنزل عليه كتابًا استنقذَكم به مما كنتم فيه،\nوإني أشهدُ أن لا إلهَ إلا اللهُ وحدَه لا شريكَ له وأن محمدًا عبدُه ورسولُه وقد جئتكم من عندِه بما أمرَكم به ونهاكم عنه\nيعني بيقول لهم الآلهة إللي انتم خايفين منها دي ولا ليها أي لازمة، لا بتضر ولا بتنفع ولا تقدر تعملي حاجة، \nوربنا أرسل لكم رسول ومعاه كتاب عشان ينقذكم من جهالة الكفر إللي انتم فيها،\nوأنا خلاص أسلمت وأشهد ألا إله إلا الله وأن محمدًا عبده ورسوله، وأنا جيت لكم من عنده ومعايا إللي أمر بيه وإللي نهى عنه، وقعد يشرح لهم الإسلام، \nتخيلوا بقى إن ما أمسَى في ذلك اليومِ وفي حاضرِه رجلٌ ولا امرأةٌ إلا مسلمًا\nيعني اليوم ده معدّاش إلا وكل إللي كانوا موجودين عنده سواء رجل أو امرأة إلا ودخلوا في الإسلام، وكانوا عدد كبير.\nعرفتوا بقى ليه عبد الله بن عباس قال عن ضِمَام بن ثَعْلبة:\n\"ما سمعنا بوافدِ قومٍ كان أفضل من هذا الوافد\" \nالوفد الثالث إللي جاء لرسول الله ﷺ ويُعتبر من الوفود المهمة برده، هو وفد نجرن النّصراني،\nولو تفتكروا في أول حلقة في السيرة اتكلمنا عن مدينة نجران وإزاي دخل أهلها في النصرانية على يد الراهب النصراني إللي كان على التوحيد على دين عيسى عليه السلام، وكان قطاع الطرق أسروه وباعوه لواحد من أهل نجران وبعد ما الراهب دعا ربنا إنه يهلك الشجرة إللي كان بيعبدها أهل نجران وربنا فعلا أهلكها بصاعقة دخلوا كلهم في دين النصرانية،\nممكن ترجعوا للقصة بالتفصيل في الجزء الأول من السيرة\nالمهم،\nدلوقتي أهل نجران أرسلوا وفد من عندهم لرسول الله ﷺ في المدينة، والوفد ده كان فيه أربعة عشر وافداً، وفي روايات بتقول إن الوفد وصل إلى ستين رجلاً،\nوصل الوفد بهيئة منظمة جداً، وفي صورة منمّقة وصلت حد المُبالغة، فقد لبسوا الثياب الحريرية وتحلّوا بالذهب، والإسلام يحرم الحرير والذهب على الرجال، \nفكرِهَ رسول الله ﷺ إنه يتكلم معهم وهمّ على الهيئة دي،\nفتأجل الحوار لتاني يوم وجاءوا لرسول الله ﷺ وهم لابسين ملابس الرهبان،\nفي حديث بيقول:\nلَمَّا قَدِمَ وَفْدُ نَجْرَانَ عَلَى رَسُولِ اللهِ ﷺ دَخَلُوا عَلَيْهِ مَسْجِدَهُ بَعْدَ صَلَاةِ الْعَصْرِ، فَحَانَتْ صَلَاتُهُمْ، فَقَامُوا يُصَلُّونَ فِي مَسْجِدِهِ، فَأَرَادَ النَّاسُ مَنْعَهُمْ،\n فَقَالَ رَسُولُ اللهِ ﷺ: دَعُوهُمْ، فَاسْتَقْبَلُوا الْمَشْرِقَ، فَصَلَّوْا صَلَاتَهُمْ\nيعني الوفد لما جاء وجاء وقت صلاة النصارى قاموا يصلوا في المسجد النبوي، فالصحابة كانوا عايزين يمنعوهم فرسول الله ﷺ قال للصحابة سبوهم يصلوا صلاتهم.\nوطبعا الكلام ده غير صحيح والحديث لا يصح أصلا عن رسول الله ﷺ\nوللأسف كتير من الدعاة والمشايخ بيقولوه من غير ما يوضحوا إنه لا يصح عن رسول الله ﷺ،\nإزاي يعني رسول الله ﷺ هيسيبهم يصلوا صلاة الكفر في المسجد النبوي،\nوحتى معنى الحديث منكر، إزاي يعني رسول الله ﷺ هيسمح لناس تقعد تشتم ربنا في المسجد النبوي وأمامه ﷺ\nوفد نصارى نجران ده مكنش له أي نية للدخول في الإسلام، همّ جايين بس عشان يجادلوا ويناظروا رسول الله ﷺ ويبهروه ويبهروا المسلمين بكلامهم وملابسهم وبتصرفاتهم،\nفالحوار معاهم كان حوار مختلف عن باقي الحوارات مع الوفود التانية،\nرسول الله ﷺ عرض عليهم الإسلام لكنهم رفضوا وبدأوا يقولوا الشُّبَه ويجادلوا في عيسى عليه السلام،\nطبعا في روايات وكلام كتير ذكره أهل السِّيَر، في منها الضعيف وفي إللي مش لاقية له تخريج أصلا\nوهم بيذكروا الروايات دي من باب الاستئناس، وهتلاقوا الروايات دي موجودة في البداية والنهاية لابن كثير الجزء الخامس،\nهتلاقوا الرابط في التعليقات عشان إللي عايز يوسع معلوماته ويعرفها\nلكن أنا مش هتكلم عنها لأن احنا إللي يهمنا الصحيح الواضح،\nوالصحيح إللي ورد هو إن وفد نصارى نجران قعدوا يجادلوا رسول الله ﷺ في عيسى بن مريم عليه السلام ويقولوا إنه إله وابن إله،\nلكن رسول الله ﷺ وضّح لهم إنه بشر زي أي بشر وهو عبد الله ورسوله،\nوقرأ عليهم القرآن إللي ربنا أنزله ساعتها وهي صدر سورة آل عمران، بما فيها قصة عيسى إللي موجودة في سورة آل عمران،\nممكن ترجعوا لقصة عيسى عليه السلام في قصص الأنبياء لو تحبوا،\nوكان من ضمن اعتراضهم إن عيسى ملوش شبيه في الخلق،\nيعني قالوا لرسول الله ﷺ:\n\" هل رأيت ولداً من غير ذَكَرٍ؟\"\nفربنا أنزل من ضمن الآيات برده في سورة آل عمران وإللي رسول الله ﷺ قرأها عليهم آية:\n\"إِنَّ مَثَلَ عِيسَى عِنْدَ اللَّهِ كَمَثَلِ آدَمَ خَلَقَهُ مِنْ تُرَابٍ ثُمَّ قَالَ لَهُ كُنْ فَيَكُونُ\"\nيعني متعجبين ومستغربين إزاي عيسى اتخلق من غير ذَكر؛ طيب ما هو خلق آدم أعجب منه، اتخلق من غير ذكر ولا أنثى، وكان مجرد تراب واتحول لبشر بصنع الله له\nوالنصارى يا جماعة لا ينكرون إن آدم عليه السلام خُلق من غير أب ولا أم، ده الكلام ده موجود في كتبهم، \nفمادام ربنا عز وجل قادر على خلق آدم عليه السلام بدون أب ولا أم وانتم مقتنعين بكده فإيه المشكلة يعني لما يخلق عيسى عليه السلام بأم فقط وبدون أب؟\nالكلام منطقي والعقل يقبله\nلكن إللي لا يقبله العقل أبدا إن الإله يبقى بشر يأكل ويشرب وينام ويُصاب بالألم ويُجرح، لأ وكمان يُقتل ويُصلب زي ما هو معروف عند النصارى\n لكن احنا كمسلمين نؤمن إن عيسى عليه السلام لم يُقتل ولم يُصلب بل رفعه الله إليه، وهينزل آخر الزمان زي ما شرحنا في قصته في قصص الأنبياء،\nالمهم برده قعدوا يجادلوا بعد ما رسول الله ﷺ شرح لهم وفهمهم،\nهنا بقى نزلت آية المُبَاهَلَة أو المُلاعَنَة، إيه هي الآية دي، وإيه موضوع المُبَاهَلَة ده\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 235, "l": "الجزء 209 | وفد نصاري نجران والمباهله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وتسعة\n#أحداث_السنة_التاسعة_من_الهجرة\n#وفد_نصارى_نجران_والمُبَاهَلَة\nاتكلمنا المرة إللي فاتت عن وفد نصارى نجران ووقفنا عند نزول آية المُبَاهَلَة، إللي هي:\n\" فَمَنْ حَاجَّكَ فِيهِ مِن بَعْدِ مَا جَاءَكَ مِنَ الْعِلْمِ فَقُلْ تَعَالَوْا نَدْعُ أَبْنَاءَنَا وَأَبْنَاءَكُمْ وَنِسَاءَنَا وَنِسَاءَكُمْ وَأَنفُسَنَا وَأَنفُسَكُمْ ثُمَّ نَبْتَهِلْ فَنَجْعَل لَّعْنَتَ اللَّهِ عَلَى الْكَاذِبِينَ\"\nيعني ربنا بيقول لرسول الله ﷺ إللي هيجادلك في عيسى بعد ما بيّنت له ووضحت له الحق بالدليل القطعي؛ قول له تعال وهات أهلك وأبناءك، وأنا هجيب أهلي وأبنائي وهنقف قصاد بعض ندعي ربنا إنه ينزل عقوبته ولعنته على إللي بيكذب فينا في شأن عيسى عليه السلام،\nيعني رسول الله ﷺ بيقول إن عيسى عبد الله ورسوله، ووفد النصارى بيقولوا إن عيسى إله وابن إله، فالكاذب هو إللي هتنزل عليه لعنة الله، يعني بمجرد ما هنبتهل هتنزل اللعنة مباشرة\nفوافق وفد نصارى نجران على المباهلة،\nالطبيعي إنهم لو واثقين في نفسهم ومتأكدين إنهم على حق ومن إن محمد ﷺ مش رسول وبيدعي النبوة مش هيخافوا أبدا من المباهلة دي، وهيدخلوا فيها بقلب جامد\nتاني يوم جاء رسول الله ﷺ بعلي بن أبي طالب وفاطمة والحسن والحسين وقال لهم:\n\"اللهم هؤلاء أهلي\"\nوبدأ يستعد للدعاء وقالهم لما أَدعُوا أمّنُوا على دعائي،\nفلما شاف الوفد إن رسول الله ﷺ جاد في موضوع المُبَاهَلَة خافوا واجتمعوا مع بعض وكان في واحد منهم اسمه السَّيِّدُ وده كان رئيسَهم، وواحد تاني اسمه العاقبُ وده كان صاحب مَشورَتِهم، يعني إللي بيقول لهم عليه بيعملوه فالسيد والعاقب مِن أكابِرِ نصارى نَجْرانَ وحكَّامِهم، \nفقالَ أحَدُهُما لِصاحِبِهِ: \"\nلا تَفْعَلْ، فَواللَّهِ لَئِنْ كانَ نَبِيًّا فَلاعَنَّا لا نُفْلِحُ نَحْنُ، ولا عَقِبُنا مِن بَعْدِنا\"\nيعني واحد من أكابر النصارى الاتنين دول قال للتاني بلاش موضوع المباهلة ده لأنه لو كان فعلا نبي واللعنة نزلت علينا يبقى ضعنا خلاص احنا وذريتنا من بعدنا\nفرفضوا إنهم يباهلوا رسول الله ﷺ وطلبوا منه إنه يحكم فيهم، فصالحهم رسول الله ﷺ على إنهم يدفعوا الجزية،\nولو فعلا كانوا باهلوا رسول الله ﷺ كان ربنا هيهلك أهلهم وأموالهم زي ما رسول الله ﷺ قال:\n\" ولو خرَجَ الذين يُباهِلونَ رسولَ اللهِ ﷺ لرَجَعوا لا يجِدونَ مالًا ولا أهلًا\"\nلما  وفد نصارى نجران قرروا إنهم يرجعوا إلى بلادهم طلبوا من رسول الله ﷺ إنه يرسل معاهم رجل أمين عشان يقبض منهم الجزية، قالوا:\n\"ابْعَثْ معنا رَجُلًا أمِينًا، ولا تَبْعَثْ معنا إلَّا أمِينًا\"\nفقال لهم رسول الله ﷺ:\n\"لَأَبْعَثَنَّ معكُمْ رَجُلًا أمِينًا حَقَّ أمِينٍ\"\nيعني هرسل معاكم واحد مفيش حد زيه في أمانته، فالصحابة لما سمعوا رسول الله ﷺ بيقول كده كل واحد فيهم تمنى إنه يكون الشخص ده، فقال رسول الله ﷺ:\n\"قُمْ يا أبا عُبَيْدَةَ بنَ الجَرَّاحِ\"\nفلما قام أبو عبيدة قال رسول الله ﷺ: \nهذا أمِينُ هذِه الأُمَّةِ\nدي كانت قصة المباهلة إللي وردت في الأحاديث الصحيحة،\nعندنا بقى كم سؤال محتاجين نجاوب عليهم،\n◇السؤال الأول:\nهل المباهلة خاصة برسول الله ﷺ فقط ولّا هو تشريع عام للمسلمين \nالمباهلة ليست خاصة برسول الله ﷺ مع النصارى، لكن هي تشريع عام له ولأمته ﷺ مع النصارى وغيرهم؛ لأن الأصل في التّشريع العموم مادام مفيش دليل تاني بيقول إن التشريع ده خاص بشخص وزمن معين\n◇السؤال الثاني:\nإيه هي اللعنة، هيحصل إيه يعني\nاللعنة هي الطرد من رحمة الله، وبالتالي مش هيبقى في لُطف من الله بالعبد في الدنيا،\nومش معنى إن اللعنة تنزل على حد إنه يبقى خلاص هيهلك في التو واللحظة،\n زي إبليس مثلا، هو مش إبليس ملعون\nلكنه مش هالك لسه موجود لحد يوم القيامة،\nوممكن يكون في ناس ملعونين وبيتحركوا بينا وبيروحوا وبييجوا عادي جدا وهم نفسهم مش حاسين ولا عارفين،\nممكن يكون واحد ملعون وعنده مال وأولاد وغرقان في مُتع الدنيا عادي جدا،\nهي المسألة تتعلق بالمصير النهائي في الآخرة، \nففي ناس ملعونين ربنا يعجل بهلاكهم في الدنيا زي ما كان هيحصل مع وفد نصارى نجران لو باهلوا رسول الله ﷺ،\nوفي ناس تانية نزلت عليهم اللعنة لكن ربنا يطيل في أعمارهم لزيادة العذاب عليهم في الآخرة،\n فالموضوع مش زي ما الناس فاهمة إن بعد المباهلة هنستنى فترة معينة وبعدين هينزل الهلاك على فلان إللي على باطل وحصل بينه وبين أهل الحق مباهلة\nممكن يحصل الهلاك في الدنيا وممكن لأ، فالعبرة بالمصير في الآخرة\n◇السؤال الثالث:\nامتى الواحد يلجأ للمباهلة\nالمباهلة لازم تكون في أمر هامٍّ من أمور الدين، ويُرجى في إقامتها حصول مصلحة للإسلام والمسلمين، أو دفع شَر المُخالف،\nوطبعا المباهلة بتكون بعد إقامة الحُجّة على المخالف،\nيعني بعد ما نبين له الحق بكل الأدلة الواضحة والبراهين القاطعة،\nزي ما رسول الله ﷺ وضّح لنصارى نجران بالأدلة الواضحة على إن عيسى عليه السلام عبد لله ورسوله وليس إله،\nفلو بعد توضيح وإظهار الحق استمر المخالف على ضلاله وعناده هنا نلجأ للمباهلة\nلكن خدوا بالكم \nالمباهلة لا تجوز في المسائل الاجتهادية التي يسوغ فيها الاختلاف،\nيعني مثلا القنوت في صلاة الفجر كل يوم، بعض أهل العلم بيقول إنه يُستحب للإمام أن يدعو دعاء القنوت في صلاة الفجر دائمًا،\nوبعض أهل العلم قالوا: لا يُستحب إلا في النوازل إذا حدث حادث، يعني مثلا لو قامت حرب ضد المسلمين يقنت المسلمون في الصلاة يدعون على العدو الذي حدث ضرره على المسلمين،\nفهنا مينفعش للفريقين المخالفين لرأي بعض إنهم يتباهلوا وخصوصا إن الفريقين مسلمين وكل واحد مستند في رأيه على دليل\nلكن لما واحد والعياذ بالله يتهم أم المؤمنين عائشة رضي الله عنها إنها وقعت في الفاحشة ومُصِر على كده وبينشر وبيشيع ده بين المسلمين مع إن ربنا أنزل براءتها في القرآن فده مش نباهله بس لأ، ده كمان حده القتل،\nوطبعا إللي يُقيم الحد هو حاكم المسلمين أو مَن ينُوب عنه\nفخلاصة الكلام إن المباهلة لا تجوز إلا في أمر مهم شرعا وقع فيه اشتباه وعناد مش هنقدر ندفعه إلا بالمباهلة،\nوتكون بعد إقامة الحجة ومن أهم شروط المباهلة:\nإخلاص النية لله تعالى\nيعني يكون الغرض من المُباهلة إحقاق الحق ونصرة أهله وإبطال الباطل وخذلان أهله، ولا يكون الهدف منها الرغبة في الغَلَبة وحب الظهور والانتصار للهوى وغيرها من أهواء النفس.\n◇السؤال الرابع:\n رسول الله ﷺ كان ساعتها متزوج من تسع زوجات، اشمعنى يعني أتى بالسيدة فاطمة وعلي بن أبي طالب والحسن والحسين فقط ولم يأتِ بأحد من زوجاته مثلا \nلأن في المباهلة الإنسان بيختار أقرب الناس منه نسبا مش الأفضل عنده من أصحابه وغيرهم؛ لأن طبيعة البشر إنهم  بيخافوا على أهلهم وذريتهم،\nوده إللي خلّى وفد نصارى نجران يتراجعوا لأنهم خافوا على أهلهم وذريتهم،\nفساعتها مكنش حد قريب في النسب من رسول الله ﷺ غير فاطمة والحسن والحسين وعلي رضي الله عنهم أجمعين،\nفكل بنات رسول الله ﷺ كانوا ماتوا ساعتها ولم يتبقّ غير فاطمة رضي الله عنها،\nوالحسن والحسين سِبْطا رسول الله ﷺ فهما بمنزلة الأبناء، وعلي رضي الله عنه ابن عم رسول الله ﷺ وزوج بنته وفي مقام ابنه؛ لأن رسول الله ﷺ لو تفتكروا كان أخد علي من عمه أبو طالب ورباه في بيته من صغره،\nومع إن إبراهيم ابن رسول الله ﷺ كان موجود ساعتها لكنه كان لسه طفل رضيع لا يعِي،\nففاطمة وعلي والحسن والحسين كانوا أخص أهل بيت رسول الله ﷺ ساعتها،\nفالكلام مفيش فيه أي دلالة على أنهم أفضل هذه الأمة؛ لأن في الصحابة من هم أفضل منهم زي أبو بكر الصديق رضي الله عنه، لكن بنتكلم عن الأقرب في النَّسَب\n《الكلام من كتب: منهاج السنة النبوية ومجموع الفتاوى لابن تيمية》\nنرجع نشوف باقي الوفود\nمن الوفود إللي جاءت لرسول الله ﷺ وفد بني أَسَد بن خُزَيْمة، وكانوا عشرة رجال، فيهم :\n《وَابِصَة بن مَعبد》و《طُلَيْحَة بن خُوَيْلد》\nوزعيهم حَضْرَمِي بن عامر وهو إللي تكلم مع رسول الله ﷺ،\nقبل ما نعرف قال إيه لرسول الله ﷺ خلونا نعرف مين وابصة بن معبد وطُلَيْحَة بن خُوَيْلد،\nوابصة بن معبد ده صاحب حديث استفتِ قلبك إللي كل الناس تقريبا حافظاه\nخلونا نشوف إيه حكاية الحديث ده\nوابصة بن معبد بيحكي عن نفسه وبيقول:\nأَتَيْتُ رَسُولَ اللَّهِ ﷺ وَأَنَا أُرِيدُ أَنْ لَا أَدَعَ شَيْئًا مِنَ الْبِرِّ وَالْإِثْمِ إِلَّا سَأَلْتُهُ عَنْهُ،\nفَأَتَيْتُهُ وَهُوَ فِي عِصَابَةٍ مِنَ النَّاسِ يَسْتَفْتُونَهُ  فَجَعَلْتُ أَتَخَطَّاهُمْ فَقَالُوا:\nإِلَيْكَ يَا وَابِصَةُ عَنْ رَسُولِ اللَّهِ ﷺ!\nفَقُلْتُ: دَعُونِي أَدْنُو مِنْ رَسُولِ اللَّهِ ﷺ فَإِنَّهُ أَحَبُّ النَّاسِ إِلَيَّ أَنْ أَدْنُوَ مِنْهُ.\nيعني وابصة بيقول إنه بعد ما أسلم جاء لرسول الله ﷺ وهو نيته إنه مش هيسيب أي حاجة من الخير أو الشر إلا وهيسأل عنها رسول الله ﷺ،\nفلما جاء لقى رسول الله ﷺ قاعد مع مجموعة من الصحابة بيستفتوه، فبدأ يعدي منهم عايز يوصل لرسول الله ﷺ،\nفهنا الصحابة المجتمعين قالوا له ابعد عن رسول الله ﷺ ومتزاحمش،\nفقال لهم سيبوني أقرب منه، فهو أكتر حد أحب إني أقرب منه،\nكل ده ورسول الله ﷺ شايف الموقف، فقال رسول الله ﷺ:\n\"دَعُوا وَابِصَةَ،\nادْنُ يَا وَابِصَةُ، جِئْتَ تَسْأَلُنِي عَنْ الْبِرِّ وَالْإِثْمِ؟\nفَقَالَ وابصة: نَعَمْ.\nفَجَمَعَ رسول الله ﷺ أَنَامِلَهُ فَجَعَلَ يَنْكُتُ بِهِنَّ فِي صَدْر وابصة وَيَقُولُ:\n يَا وَابِصَةُ اسْتَفْتِ قَلْبَكَ وَاسْتَفْتِ نَفْسَكَ ثَلَاثَ مَرَّاتٍ،\n الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ وَالْإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ\"\nرسول كان بيقول لوابصة الكلام ده وهو بيخبط على صدره بأطراف أصابعه ﷺ.\nوالحديث معناه إن المؤمن صاحب القلب السليم ممكن يستفتي حد من العلماء في شيء فيفتيه بأنه حلال،\nولكن يقع في نفس المؤمن حَرج من فعل الأمر ده ويبقى مش مرتاح للفتوى دي ومش قادر إنه يعمل بالفتوى،\nفهنا يجب عليه إنه يترك العمل بالفتوى ويتبع ما إللي في قلبه\nبس استنووووا\nأنا قلت لكم قبل كده في بداية السيرة في الجزء الثامن إن\nالكلام ده \n للمؤمن صاحب القلب السليم\nيعني ميجيش واحد غرقان في المعاصي والمُوبقات وتقوله حلال وحرام يقول لك:  هستفتي قلبي\nأهه ده لو استَفْتى قلبه في الكبائر مثلا...قلبه هيقول له: \nحلالٌ حلالٌ حلال \nاحنا بنتكلم عن قلب المؤمن التقي إللي مش بيتبع هواه وبيشوف ربنا يريد إيه ويعمله وهو حريص على إنه يرضي ربنا،\nفالواحد لما يسمع الفتوى من حد ونفسه مش مطمئنة للفتوى  دي لا يجوز له إنه يعمل بيها\nوابن القيم بيقول:\n\"لا يجوز العمل بمجرد فتوى المفتي إذا لم تطمئن نفسه وحاك في صدره من قبوله وتردد فيها؛ لقوله ﷺ:\n\"استفت نفسك وإن أفتاك الناس وأفتوك\"\nوهتلاقوا في موقع الإسلام سؤال وجواب تفصيل المسألة، الرابط في التعليقات\nنيجي بقى لطُلَيْحَة بن خُوَيْلد،\nهو أسلم دلوقتي مع الوفد، لكن بعد موت رسول الله ﷺ هيرتد عن الإسلام، ومش بس كده\n \nده كمان هيدّعي النبوة وقومه بني أسد هيرتدوا وهيتّعبوه وهيحصل قتال بينهم وبين خالد بن الوليد وهيغلبهم خالد رضي الله عنه،\nوفي النهاية هيرجع طُلَيْحَة بن خُوَيْلد والباقي من بني أسد للإسلام مرة تانية وهيحسن إسلامه ويموت على الإسلام، وبني أسد هيكون لهم كبير في معركة القادسية،\nهنعرف التفاصيل دي إن شاء الله لما ييجي وقتها\nنرجع لحَضْرَمِي بن عامر ونشوفه قال إيه لرسول الله ﷺ، قال حَضْرَمِي بن عامر:\nقاتلتكَ مُضَر، ولسنا بأقلّهم عددا، ولا أَكَلِّهِمْ《يعني أضعفهم》 شَوْكة، ووصَلْنا رحِمَك\"\nوفي رواية تانية قال: \n\"يا رسول الله!\nإنا شهدنا أن الله وحده لا شريك له، وأنك عبده ورسوله، وجئناك يا رسول الله، ولم تَبْعَث إلينا بعْثاً، ولم نقاتلك كما قاتَلتْك العرب\"\nيعني بيقول لرسول الله ﷺ احنا أسلمنا من غير ما نقاتلك زي العرب ما قاتلوك، وجئناك من غير حتى ما تبعت لنا حد يدعونا للإسلام، واحنا وصلنا رحمك ولم نقطعه زي باقي قريش؛ لأن بني أسد ورسول الله ﷺ كانوا من فرع مُضَر، يعني من سُلالة واحدة، \nفبيقولوا لرسول الله ﷺ متفكرش يعني إن احنا أسلمنا مننا لنفسنا كده عشان احنا ضعفاء مثلا أو عددنا قليل ولّا خايفين منك، \nلأ، احنا أقوياء بس احنا إللي جايين بمزاجنا واختيارنا\nفهنا نزل القرآن\nقال تعالى في آخر سورة الحُجُرات:\n\" يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا قُلْ لَا تَمُنُّوا عَلَيَّ إِسْلَامَكُمْ بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَاكُمْ لِلْإِيمَانِ إِنْ كُنْتُمْ صَادِقِينَ\"\nالمَن معناه تِعداد النعم على الغير، يعني الواحد يقعد يقول للتاني أنا عملت لك كذا وكذا ويقعد يعدد عليه الحاجات الكويسة إللي عملها للطرف التاني،\nفالجماعة إللي جايين دول بيمنوا على رسول الله ﷺ إنهم لم يقاتلوه زي باقي الناس وأسلموا من غير ما رسول الله ﷺ يبعت لهم رسالة ولا أي حاجة، \nفربنا بيقول لرسول الله ﷺ يقول لهم لأ، محدش يتفاخر  علىَّ بسبب إسلامكم؛ لأن ثمرة هذا الإِسلام هيعود نفعها عليكم مش عليّ أنا،\nثم لو جينا للحق بقى فربنا بفضله وكرمه هو إللي هداكم للإسلام، الموضوع بشطارتكم يعني، فلله الفضل والمنة، ده إذا كنتم فعلا صادقين في إيمانكم\n☆خدوا بالكم إن الآية مش بس مُوجّهة للمجموعة دي من بني أسد، دي موجهة لكل مسلم،\nساعات الواحد لما بيعمل طاعات وبيفرح بيها زيادة عن اللزوم بينسى فضل ربنا عليه وبيفكر بقى إن الطاعات دي عملها بشطارته مش إن ربنا اصطفاه ووفّقه لها في حين إن غيره غرقان في الكفر والمعاصي\nفلازم نفهم كويس إن ربنا هو إللي له الفضل والمِنّة إنه بيوفقنا لعمل الطاعات.\nوعشان بس محدش يفهم غلط، الفرح بعمل الطاعات من علامات الإيمان، رسول الله ﷺ بيقول:\n\"من سرَّتْهُ حسنتُهُ وساءتْهُ سيِّئتُهُ فهو مؤمنٌ\"\nيعني إللي بيعمل طاعة ويفرح إنه عملها ولو عمل سيئة يزعل إنه عملها فده المؤمن،\nلكن إللي يبقى فرحان ومُعجب بنفسه ومفكر إنه بشطارته بيعمل الطاعات ومش شايف فضل ربنا عليه ولما حد ينصحه بإنه يزود الطاعات ويبعد عن المنكرات يقوم يقوله مش كفاية إني بعمل كذا وكذا وكذا وغيري مبيعملش\nده أنا جزاني الله خيرا إني بعمل كذا كذا،  ده انتم تحمدوا ربنا إني موقعتش في المحرمات والكبائر و...و....\nهو ده بقى هو إللي بيبقى في خطر ومُعرّض إن عمله يُحبط للأسف، فناخد بالنا\nإن شاء الله المرة الجاية هنكمل الكلام عن باقي الوفود إللي جاءت لرسول الله ﷺ في السنة التاسعة من الهجرة"}, {"n": 236, "l": "الجزء 210 | لا ترفعوا أصواتكم فوق  صوت النبي", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وعشرة\n#أحداث_السنة_التاسعة_من_الهجرة\n#لا_ترفعوا_أصواتكم_فوق_صوت_النبي\nمن الوفود إللي جاءت لرسول الله ﷺ في السنة التاسعة للهجرة وفد بني تميم،\nلما جاء الوفد اقترح أبو بكر الصديق رضي الله عنه على رسول الله ﷺ إن إللي يتكلم ويكون هو المسؤول عن تمثيل وفد بني تميم واحد اسمه القعقاع بن مَعبِد،\nفهنا عمر قال لرسول الله ﷺ: لأ، خلي الأقرع بن حابس هو المسؤول،\nفأبو بكر الصديق قال لعمر: ما أردت إلا خِلَافِي!\nيعني انت عايز تخالفني وخلاص عشان كده اقترحت اسم تاني غير إللي أنا اقترحته،\nفعمر قال لأبي بكر: ما أردتُ خِلافَك!\nيعني أنا مش عايز أخالفك ولا حاجة زي ما انت فاهم،\nفحصل بينهم جدال وأصواتهم ارتفعت وكل ده أمام رسول الله ﷺ،\nفنزل القرآن\nقال الله تعالى في بدايات سورة الحجرات:\n\" يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا بَيْنَ يَدَيِ اللَّهِ وَرَسُولِهِ وَاتَّقُوا اللَّهَ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ ۩\n يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلَا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لَا تَشْعُرُونَ ۩\n إِنَّ الَّذِينَ يَغُضُّونَ أَصْوَاتَهُمْ عِنْدَ رَسُولِ اللَّهِ أُولَئِكَ الَّذِينَ امْتَحَنَ اللَّهُ قُلُوبَهُمْ لِلتَّقْوَى لَهُمْ مَغْفِرَةٌ وَأَجْرٌ عَظِيمٌ\"\nيعني إيه الآيات دي بقى\nيعني ربنا بيقول للصحابة لا تُسرِعوا في الأشياء بين يديه، بمعنى إنكم تستنوا رأي رسول الله ﷺ وتشوفوا هو هيقول إيه الأول وتكونوا تَبَع له، \nوالموقف هنا إن محدش منهم يستعجل ويستبق الأمور ويقدم الرأي ويعرض على رسول الله ﷺ مين إللي يكون مسؤول،\nلو رسول الله ﷺ طلب رأيهم ماشي، لكن إنهم منهم لنفسهم كده يتكلموا وكمان الموضوع يقلب بخناقة فده مينفعش خالص،\nحتى لو كان إللي اقترحوا واتكلموا وأصواتهم ارتفعت عند رسول الله ﷺ هما الخَيِّرَانِ أبي بكر وعمر زي ما جاء في الحديث:\n\"كَادَ الخَيِّرَانِ أنْ يَهْلِكَا أبو بَكْرٍ وعُمَرُ رَضِيَ اللَّهُ عنْهمَا\"\nو الخَيِّرَانِ معناها إللي بيعملوا الخير الكثير،\nوكادا أن يهلكا بسبب رفع أصواتهم أمام رسول الله ﷺ وتقديم الرأي قبل ما رسول الله ﷺ يتكلم أصلا،\nوربنا نهى الصحابة إنهم يرفعوا أصواتهم عند رسول الله ﷺ أو إنهم يكلموه زي ما بيكلموا بعض،\nلازم يتكلموا معاه بوقار واحترام ويوطوا أصواتهم وهم بيتكلموا معاه، عشان رسول الله ﷺ ميغضبش منهم؛ لأن ممكن ربنا يغضب لغضب رسوله ﷺ وكده كل أعمالهم الصالحة إللي عملوها تحبط،\nوربنا شجّعهم على خفض أصواتهم عند الكلام مع رسول الله ﷺ أو في حضرته بإن إللي هيعمل كده جزاءه المغفرة والأجر العظيم.\nوفعلا من بعدها عمر بن الخطاب رضي الله عنه ما كانَ  يُسمِعُ رَسولَ اللهِ ﷺ بَعدَ هذه الآيَةِ حتَّى يَستفْهِمَه، \nيعني بقى يوطي صوته خااالص وهو بيتكلم مع رسول الله ﷺ لدرجة إن رسول الله ﷺ بقى هو إللي يقوله يعلّي صوته عشان يسمعه\nلما نزلت آية عدم رفع الصوت واحد من الصحابة اسمه ثابت بن قَيس بن شمّاس طبيعته إنه صوته عالي فكان بيتكلم وبيخطب أمام رسول الله ﷺ بصوت عالي، فلما سمع الآية قال:\nأنا واللهِ الَّذي كُنْتُ أرفَعُ صوتي عندَ رسولِ اللهِ ﷺ وأنا أخشى أنْ يكونَ اللهُ قد غضِب علَيَّ\nيعني هو فكّر إن الآية دي نزلت فيه هو وإن عمله خلاص أُحبط يعني أُبطِل، ومبقاش له أعمال صالحة،\nفحزن ثابت بن قيس رضي الله عنه وقعد في بيته، وهو كان خطيب النبي ﷺ،\nفرسول الله ﷺ افتقده، يعني لقاه مش موجود ودي مش عادته فسأل عنه هو فين، فواحد من الصحابة قال لرسول الله ﷺ:\nيا رَسولَ اللَّهِ، أَنَا أَعْلَمُ لكَ عِلْمَهُ\nيعني أنا هروح أجيب لك خبره وأشوفه هو فين، فراح الرجل لبيت ثابت لقاه قاعد موطي راسه ومهموم\nفسأله الصحابي مالك في إيه\nفحكى له ثابت إن عمله خلاص أُحبط بسبب إنه كان بيرفع صوته فوق صوت النبي ﷺ وهو خايف إنه كده بقى خلاص من أهل النار،\nفالصحابي رجع لرسول الله ﷺ وأخبره بالموضوع، فقال له رسول الله ﷺ:\n\" اذْهَبْ إلَيْهِ، فَقُلْ له: إنَّكَ لَسْتَ مِن أَهْلِ النَّارِ، ولَكِنْ مِن أَهْلِ الجَنَّة\"\nيعني روح بشّره وقول إنه مش هو المقصود بالآية دي، وإنه مش من أهل النار لكنه من أهل الجنة\n◇سؤال بقى،\nهل حكم رفع الصوت على رسول الله ﷺ انتهى بموته وبالتالي مفيش حبوط للعمل، ولّا الحكم مستمر بعد موته ﷺ\nشوفوا،\nقال القاضي أبو بكر بن العربي:\n\"حُرْمة النبي ﷺ ميتاً كحرمته حياً، وكلامه المَأثُور بعد موته في الرُّقعة مثال كلامه المسموع من لفظه، \nفإذا قُرئ كلامه، وجَب على كل حاضر ألا يرفع صوته عليه، ولا يُعرِض عنه، كما كان يلزمه ذلك في مجلسه عند تلفظه به\"\nيعني الأمور إللي ربنا نهى عنها في حياة رسول الله ﷺ وخاصة بيه ﷺ مستمرة حتى بعد موته،\nوكلام وأحاديث رسول الله ﷺ وأفعاله المكتوبة في الكتب هي بالضبط زي كلامه المسموع إللي رسول الله ﷺ قاله بلسانه،\nيعني لما أنا أقول لكم مثلا حديث عن رسول الله ﷺ دلوقتي وانتم بتقرأوه فده كأن بالضبط رسول الله ﷺ واقف قصادكم وبيقول لكم الكلام،\nمثال:\nقال علي بن أبي طالب رضي الله عنه:\nإِنَّ نَبِيَّ اللَّهِ ﷺ أَخَذَ حَرِيرًا، فَجَعَلَهُ فِي يَمِينِهِ، وَأَخَذَ ذَهَبًا فَجَعَلَهُ فِي شِمَالِهِ،ثُمَّ قَالَ:\n《 إِنَّ هَذَيْنِ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي》\nيعني رسول الله ﷺ بيقول أمام الصحابة إن الحرير والذهب حرام على الرجال، \nفكل الصحابة سمعوا الكلام ومحدش بقى يلبس أي حاجة ذهب، وفي حديث تاني إن رسول الله ﷺ شاف واحد لابس خاتم ذهب فراح شاده من إيده ورماه، وقال:\n\"يَعْمَدُ أَحَدُكُمْ إِلَى جَمْرَةٍ مِنْ نَارٍ فَيجْعلهَا في يَدِهِ\"\nوالصحابي مرضاش ياخد الخاتم بعد كده حتى يبيعه وينتفع بيه، وقال:\n\"لا واللَّه لا آخُذُهُ أَبَداً وقَدْ طَرحهُ رسولُ اللَّه ﷺ\"\nدلوقتي في وقتنا الحاضر لو واحد مسلم لابس خاتم أو دبلة ذهب وقلنا له حديث رسول الله ﷺ ورفض إنه يستجيب لأمر رسول الله ﷺ ده كده بالضبط كأنه وقف أمام رسول الله ﷺ وقال له في وشه أنا مش هسمع كلامك يا رسول الله، تخيلوا كده الموقف \nفمفيش فرق بين إن رسول الله ﷺ يقول لنا الحديث وجها لوجه وبين إن الحديث يوصل لنا عن طريق حد تاني مادام الحديث《صحيح》\nفاللي يرد حديث رسول الله ﷺ الصحيح ويقعد يجادل ويُنكر حديث رسول الله ﷺ ويعلي صوته على كلام رسول الله ﷺ وميقعدش يسمع حديث رسول الله ﷺ لما بيُقال قصاده؛ ده مُعرّض لحبوط عمله وهو مش حاسس بالكارثة إللي حاطط نفسه فيها\nيعني مجرد رفع الصوت أمام رسول الله ﷺ بدون أي قصد إساءة أدب ولا أي حاجة بيحبط العمل، فما بالكم باللي يرد حديث رسول الله ﷺ الصحيح ويعترض عليه وينكره ولا يعمل به، ويقول لأ، ده كذا أفضل ومستحيل رسول الله ﷺ يقول كذا وكذا\nده حتى مينفعش رفع الأصوات عند قبر رسول الله ﷺ، \nوعمر رضي الله لما كان خليفة للمسلمين سمع صوت رجلين في مسجد النبي ﷺ قد ارتفعت أصواتهما، فجاء فقال: أتدريان أين أنتما؟\nيعني بيسألهم سؤال استنكاري؛ بينكر عليهم إللي بيعملوه: انتم عارفين انتم فين وانتم عمالين تعلوا صوتكم كده\nوبعدين سألهم: من أين أنتما؟ \nفقالا: من أهل الطائف، فقال: لو كنتما من أهل المدينة لأوجعتكما ضربا، ترفعانِ أصواتَكما في مسجِدِ رسولِ الله؟\nوعمر فرّق بينهم وبين أهل المدينة لأن أهل المدينة لا تخفى عليهم حرمة مسجد رسول الله ﷺ وتعظيمه بخلاف إللي من خارج المدينة وممكن يخفى عليه الموضوع،\nفهو عَذَر الرجلين بسبب جهلهم\nنرجع لوفد بني تميم إللي كان سبب الأزمة دي كلها\nوهم نفسهم نزل فيهم قرآن همّ كمان،\nقبل ما ييجوا لرسول الله ﷺ في المسجد اجتمعوا مع بعض وقالوا:\n\"انطلِقوا إلى هذا الرَّجلِ فإن يَكُ نبيًّا فنحنُ أسعدُ النَّاسِ بِهِ، وإن يَكُ ملِكًا نعِش بجناحِهِ\"\nيعني خلونا نتبع محمد ﷺ فلو طلع نبي يبقى احنا أسعد الناس به، ولو طلع ملك يبقى احنا تحت حمايته وهنستفيد منه، \nيعني كده كده لو اتبعناه فالموضوع في مصلحتنا،\nواحد من الصحابة اسمه زيد بن أرقم كان سمع الحوار بتاعهم ده، وأخبر رسول الله ﷺ بالقصة كلها،\nلما جاء الوفد ودخلوا المسجد رسول الله ﷺ مكنش موجود كان في بيته، واحنا عارفين إن بيوت النبي ﷺ ملاصقة للمسجد،\nفوقفوا في المسجد وقعدوا ينادوا على رسول الله ﷺ بصوت عالي:\nيا محمد! يامحمد!\nورسول الله ﷺ سمعهم ولكنه مردش عليهم، فواحد منهم قال:\nيا محمد! إن مَدحِي زَين وإن شتمي شَيْن\nيعني بيقوله اخرج وتعال كلمني، انت متعرفش أنا مين، \nده أنا لو مدحت حد هرفعه للسماء وهيبقى مشهور وهيفضل ممدوح بين للناس على طول،\nلكن لو أنا ذمّيتك وشتمتك يبقى انت خلاص كده ضعت وروحت ورا الشمس وهيبقى العار ملاحقك على طول،\nفهنا رسول الله ﷺ خرج له وقال له:\n\"ويلك ذاك الله\" \nيعني ربنا هو إللي مدحه زين وسبّه شين؛ لأن ربنا لو مدح عبد من عباده هيفضل المدح ده ملاصق له للأبد بعكس لو ربنا ذم إنسان خلاص كده هو ضاع مهما كانت له مكانة بين الماس وعنده أموال وجاه\nفنزلت الآيات:\n\" إِنَّ الَّذِينَ يُنَادُونَكَ مِنْ وَرَاءِ الْحُجُرَاتِ أَكْثَرُهُمْ لَا يَعْقِلُونَ ۩ وَلَوْ أَنَّهُمْ صَبَرُوا حَتَّى تَخْرُجَ إِلَيْهِمْ لَكَانَ خَيْرًا لَهُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ\"\nفهنا ربنا بيذم الناس إللي قعدوا ينادوا على رسول الله ﷺ \nمن وراء الحجرات، وهي بيوت نسائه ﷺ، وطبعا هم لا يعقلوا بسبب قلة العلم والبصيرة،\nوبعدين ربنا قال لو إنهم صبروا لحد ما انت تخرج لهم كان ده هيبقى الخير والمصلحة في الدنيا والآخرة، وبعدين ربنا دعاهم للتوبة والاستغفار عن إللي عملوه ده.\nفلما نزلت الآيات أخذ رسول الله ﷺ بأذن زيد بن أرقم، فمدها، وقعد يقول: \n\"لقد صدق الله تعالى قولك يا زيد، لقد صدق الله قولك يا زيد\"\nيعني رسول الله ﷺ مسك أذن زيد رضي الله عنه وشدها كده وقال له إن ربنا صدق كلامك إللي انت نقلته لي عن وفد بني تميم.\n♡ملحوظة:\nهتلاقوا في التعليقات\n رابط لدرس بيشرح تفسير سورة الحجرات لدكتور أحمد عبد المنعم،\nالدرس ده مهم جدا يا جماعة وأسلوب الشيخ سهل وبسيط هيفيدكم جدا إن شاء الله \nدي كده كانت أهم الوفود إللي جاءت لرسول الله ﷺ في السنة التاسعة من الهجرة،\nطبعا في وفود تانية كتير بس مش هقدر أتكلم عنهم كلهم لأن الموضوع هيطول أوي\nوممكن تراجعوا الجزء الرابع من كتاب:\n《السيرة النبوية كما جاءت في الأحاديث الصحيحة》\nهتلاقوا فيه باقي الوفود، ورابط الكتاب في التعليقات\nفاحنا كده عرفنا أهم الأحداث مع الوفود وإللي كانت مرتبطة بنزول بعض آيات القرآن،\nوفي طبعا وفود تانية مهمة هتيجي في السنة العاشرة للهجرة، لما نتكلم عن السنة العاشرة هنتكلم عن الوفود المهمة دي إن شاء الله\nدلوقتي احنا في شهر ذي الحجة من السنة التاسعة من الهجرة، في الوقت رسول الله ﷺ أمّر أبا بكر الصديق رضي الله عنه على الحج في هذا العام\nإيه الأحداث إللي حصلت في حجة أبي بكر؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 237, "l": "الجزء 211 | حج ابي بكر الصديق", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وإحدى_عشر\n#أحداث_السنة_التاسعة_من_الهجرة\n#حج_أبي_بكر_الصديق\nشوفنا إزاي الأوضاع في الجزيرة العربية استقرت والوفود إللي جاءت تُعلن الولاء لرسول الله ﷺ وللدولة الإسلامية،\nسواء بدخولهم في الإسلام أو إنهم يعملوا معاهدات مع رسول الله ﷺ،\nجاء بقى موسم الحج، ولحد اللحظة دي كان لسه المشركين بيحجوا لبيت الله الحرام مع المسلمين، \nوكان في بعض المشركين بيطوفوا بالكعبة وهم عرايا، عريانين يعني، ومش لابسين ملابس تغطي حتى العورة المُغلظّة\nوالكلام ده من قبل الإسلام، وقالت السيدة عائشة في حديث صحيح:\n\" كانَ النَّاسُ يَطُوفُونَ في الجَاهِلِيَّةِ عُرَاةً إلَّا الحُمْسَ، والحُمْسُ قُرَيْشٌ وما ولَدَتْ،\n وكَانَتِ الحُمْسُ يَحْتَسِبُونَ علَى النَّاسِ، يُعْطِي الرَّجُلُ الرَّجُلَ الثِّيَابَ يَطُوفُ فِيهَا،\nوتُعْطِي المَرْأَةُ المَرْأَةَ الثِّيَابَ تَطُوفُ فِيهَا، فمَن لَمْ يُعْطِهِ الحُمْسُ طَافَ بالبَيْتِ عُرْيَانًا\"\nوالحديث معناه إن قريش كانت بتمنع الناس إنهم يطوفوا بالبيت إلا وهم لابسين ملابس من قريش،\nفكان الرجل من قريش بيعطي الرجل من خارج قريش ملابس يلبسها ويطوف بيها،\nوكذلك كانت النساء، ولو محدش من قريش أعطى ثياب للقادمين من خارج قريش كانوا يطوفوا بالبيت الحرام عرايا، الرجال والنساء على السواء\nفالعادة دي لسه موجودة لحد موسم حج السنة التاسعة من الهجرة، فرسول الله ﷺ مكنش عايز يطوف بالبيت وفي مشركين بيطوفوا وكمان في ناس عرايا، فلم يخرج للحج في السنة التاسعة،\nوجعل أبو بكر الصديق أمير الحج، يعني هو إللي يقود الناس في الحج،\nخرج أبو بكر في وفد الحج وتوجه إلى مكة،\nبعد ما خرج أبو بكر رضي الله عنه نزلت بدايات سورة براءة أو سورة التوبة وفيها تشريعات مهمة في تعامل المسلمين مع المشركين، وتعتبر إعلان مصيري بالنسبة لكل مشرك في الجزيرة العربية\n☆ملحوظة:\nسورة التوبة أو سورة براءة هي آخر سور القرآن الطّوال إللي نزلت على رسول الله ﷺ،\nوسورة التوبة هي السورة الوحيدة التي لم تبدأ بالبسملة،\nوالسبب في كده إنه كان من عادة العرب إنهم لما يكونوا عايزين ينقدوا عهد مع حد مكنوش بيبدأوا رسايلهم بنقد العهد بالبسملة،\nيعني كانوا بيدخلوا في الموضوع على طول بدون قول باسمك اللهم،\nوسورة براءة نزلت لتنقض العهد مع المشركين، فلم تبدأ السورة بالبسملة على عادة العرب\nوسبب تاني لعدم ذكر البسملة وهو إن السورة فضحت المنافقين وفيها كلام شديد جدا للمنافقين والكافرين لا يتناسب مع الرحمة الموجودة في البسملة\nأمر رسول الله ﷺ علي رضي الله عنه إنه يذهب لمكة عشان يعلن للناس الأحكام الشرعية الجديدة،\nملخص الأحكام دي أربعة أحكام رئيسية هي:\n◇ لا يدخل الجنة إلا مؤمن.\n◇لا يطوف بالبيت عريان.\n◇ لا يحج البيت الحرام بعد هذا العام مشرك.\n◇مَن كان بينه وبين رسول الله ﷺ عهد فعهده إلى مدته حتى ولو كانت سنوات ما دام لم يظهر منه أي خيانة للعهد،\nفلو ظهر منه أي خيانة له أربعة أشهر فقط،\nوإللي ملوش عهد خالص من المشركين فآخر مدة عهده هي انتهاء الأشهر الحُرم، إللي هو باقي شهر ذي الحجة وشهر محرم.\nفخرج علي رضي الله عنه من المدينة متجه لمكة وكان راكب على ناقة رسول الله ﷺ القَصْواء،\nفلما جاء علي لأبي بكر سأله أبو بكر:\nأميرٌ أم مأمورٌ ؟ \nيعني انت رسول الله ﷺ أرسلك عشان تبقى أمير على الحج بدالي ولّا انت جاي توصّل رسالة فقط وتكون تحت قيادتي،\n فعلي رضي الله عنه قال:\nبل مأمورٌ\nيعني أنا جاي أوصل رسالة رسول الله ﷺ بالأحكام الشرعية إللي نزلت، \nوبعدها انطلق علي رضي الله عنه بين الناس يخبرهم بالأحكام الشرعية الجديدة.\nالآيات إللي نزلت كانت شديدة على المشركين وفيها إن الحرب مُعلنة عليهم بوضوح وقوة، ومفيش قصادهم غير اختيارين:\nإما القتال ومواجهة المسلمين، وإما الإسلام\nخلونا نشوف الآيات وتفسيرها واحدة واحدة:\n\"بَرَاءَةٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدتُّمْ مِنَ الْمُشْرِكِينَ ۩  فَسِيحُوا فِي الأَرْضِ أَرْبَعَةَ أَشْهُرٍ وَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللَّهِ وَأَنَّ اللَّهَ مُخْزِي الْكَافِرِينَ\"\nدول أول آيتين من سورة التوبة، ربنا بيقول فيهم إنه سبحانه هو ورسوله ﷺ بيتبرأوا من أهل الشرك إللي بينهم وبين رسول الله ﷺ عهد،\nطبعا يجوز دلوقتي عمل عهود بين المسلمين والمشركين، لكن في عهد رسول الله ﷺ نزلت الآية دي عشان تنهي أي عهود بين رسول الله ﷺ وبين المشركين،\nوده تمهيد لأمر رسول الله ﷺ بعدين إنه لا يبقى في جزيرة العرب لا مشرك ولا كافر، فقط المسلمين،\nفرسول الله ﷺ قال في مرض موته:\n\"أخرجوا المشركين من جزيرة العرب\"\nوقال ﷺ:\n\" لأُخرِجن اليهود والنصارى من جزيرة العرب حتى لا أدع إلا مسلماً\"\nيعني ده أمر مباشر من رسول الله ﷺ إن جزيرة العرب إللي هي الجزيرة العربية كلها التي يحيط بها البحر الأحمر والخليج العربي والمحيط الهندي وتنتهي شمالا إلى أطراف الشام والعراق لا يبقى فيها غير المسلمين فقط\nوبالتالي طبعا لا يجوز أن يُبنى في الجزيرة معابد للكفرة، سواء النصارى أو غيرهم\nفأول الموضوع هو التحلل من العهود والمواثيق مع المشركين، \nوالإعلان ده عشان محدش ييجي يقول بعد كده إن المسلمين غدروا بحد أو هم أهل غدر،\nالإعلان واضح: \nالعهد الذي بيننا وبينكم قد انتهى\nلكن لكم مهلة أربعة أشهر هتكونوا فيها آمنين مطمئنين محدش هيتعرض لكم بأذى ما دمتم لم تتعرضوا لنا بالأذى،\nومتفكروش إنكم تقدروا تهربوا من الله عز وجل بإنكم ممكن تستخبوا في مكان بعيد ولّا حاجة، واعرفوا إن ربنا هيذل ويخزي الكافرين.\nالآية الثالثة من سورة التوبة بتقول:\n\" وَأَذَانٌ مِنَ اللَّهِ وَرَسُولِهِ إِلَى النَّاسِ يَوْمَ الْحَجِّ الأَكْبَرِ أَنَّ اللَّهَ بَرِيءٌ مِنَ الْمُشْرِكِينَ وَرَسُولُهُ فَإِنْ تُبْتُمْ فَهُوَ خَيْرٌ لَكُمْ وَإِنْ تَوَلَّيْتُمْ فَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي اللَّهِ وَبَشِّرِ الَّذِينَ كَفَرُوا بِعَذَابٍ أَلِيمٍ \"\nيعني إعلان من الله ورسوله في يوم الحج الأكبر بالبراءة من المشكرين، وهنا أعلن علي رضي الله عنه الأربعة أمور إللي قلنا عليهم في الأول\nويوم الحج الأكبر هو يوم النّحر وهو فيه معظم أعمال الحج زي رمي الجمرات والحَلْق والطواف والسعي ونَحْر الهَدْي،\nويوم النحر هو اليوم العاشر من شهر ذي الحجة وهو أول أيام عيد الأضحى.\n☆ملحوظة:\nفي قول بيقول إن يوم الحج الأكبر هو يوم عرفة، لكن مفيش دليل على الكلام ده، وقول جمهور العلماء إن يوم النحر هو يوم الحج الأكبر وإللي عليه الأدلة\nربنا بيقول للمشركين في الآية لو تُبْتم يعني لو رجعتم عن الشرك فده الأحسن لكم أما لو توليتم عن الإيمان واستمريتم على الكفر فاعرفوا كويس أوي إن محدش فيكم هيفلت من عقاب الله، \nوربنا أمر رسول الله ﷺ إنه يبشر الكفار بعذاب أليم مُوجِع\nفي الآية إللي بعدها الآية الرابعة ربنا استثنى من براءة العهود مع المشركين بعض العهود،\nوهي عهود الكفار إللي أوفوا بعهدهم لرسول الله ﷺ والمؤمنين ولم يظهر منهم أي خيانة للمؤمنين،\nفالنوع ده من المشركين ربنا أمر إن عهدهم يمتد لحد ما ينتهي أجله إللي متفقين عليه حتى لو كان العهد ده مدته سنوات،\nوهو سبحانه يحب المتقين الذين يوفون بعهودهم ولا ينقضونها\nالآية بتقول:\n\" إِلَّا الَّذِينَ عَاهَدتُّم مِّنَ الْمُشْرِكِينَ ثُمَّ لَمْ يَنقُصُوكُمْ شَيْئًا وَلَمْ يُظَاهِرُوا عَلَيْكُمْ أَحَدًا فَأَتِمُّوا إِلَيْهِمْ عَهْدَهُمْ إِلَىٰ مُدَّتِهِمْ ۚ إِنَّ اللَّهَ يُحِبُّ الْمُتَّقِينَ\"\n☆طيب إيه إللي هيحصل يعني بعد ما مدة العهد تنتهي \nسواء الأربع شهور أو انتهاء الأشهر الحرم\nربنا بيقول في الآية إللي بعد كده:\n\"فَإِذَا انسَلَخَ الأَشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ وَخُذُوهُمْ وَاحْصُرُوهُمْ وَاقْعُدُوا لَهُمْ كُلَّ مَرْصَدٍ فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ\"\nالآية دي\n بعض العلماء بيسموها 《آية السيف》، ومعنى الآية إن لما مدة العهد تنتهي سواء الأشهر الحرم أو الأشهر الأربعة فاقتلوا المشركين في أي مكان تقابلوهم وخذوهم أسرى وضيّقوا عليهم فلا تدعوهم يتوسعون في بلاد الله وأرضه، \nفهم لا يستحقوا إنهم يسكنوا فيها؛ لأن الأرض أرض الله، وهم أعداؤه المعارضون والمحاربون له ولرسوله،\nواقعدوا لهم على كل مكان ممكن يعدّوا عليه، ورابطوا في جهادهم وابذلوا كل مجهودكم في جهادهم واستمروا على كده لحد ما يتوبوا من شركهم\nالكلام في الآية عن المشركين زي إللي بيعبدوا الأصنام وغيرها، أما المجوس وأهل الكتاب من اليهود والنصارى فإذا دفعوا الجزية فخلاص كده يخرجوا من الآية ولا يقاتلهم المسلمون،\nأما لو رفضوا دفع الجزية فالمسلمين يقاتلوهم زي ما بيقاتلوا المشركين.\n☆وعشان محدش يفهم الكلام غلط ويفكر إن الجيوش المسلمة لما تشوف أي مشرك تقتله لمجرد إنه مشرك؛ ففي شروط لقتال المشركين\nيعني يكون المشركين إللي يجب قتالهم دول مثلا اعتدوا على المسلمين بسَلْب أو نهب أو اغتصاب لحقوق المسلمين، \nأو بسبب منعهم للمسلمين من نشر الإسلام وإيصاله إلى غيرهم، \nفبدون الأمور دي لا يجوز قتال المشركين، وده إللي حصل في الفتوحات الإسلامية، \nمكنش الصحابة ولا إللي جاءوا من بعدهم بيقاتلوا المشركين لمجرد إنهم مشركين، لأ، كانوا بيقاتلوا الجيوش المشركة إللي كانت بتمنع وصول رسالة الإسلام للناس بصفة عامة\n أما في عهد رسول الله ﷺ بعد نزول آية السيف فكان يقاتل المشركين من العرب لو مدخلوش في الإسلام؛\nلأن العرب المشركين دول ربنا أمر بقتالهم لأنهم محاربين لرسول الله ﷺ ولدولته ومُعلنين للحرب دي لأكثر من عشرين سنة متصلة، \nوالأصل في الأمور إن الحرب ما زالت مستمرة، ولن يتم إيقاف الحرب حتى يُسلم المشركون،\nفلو رفضوا الإسلام فالأمور على طبيعتها الأولى وهي استمرار الحرب، \nلكن لو تابوا ودخلوا في الإسلام وأقاموا الصلاة وأدّوا الزكاة فخلاص عصموا دماءهم وربنا هيغفر لهم ما فات،\nزي ما ربنا قال:\n\" فَإِنْ تَابُوا وَأَقَامُوا الصَّلاةَ وَآتَوُا الزَّكَاةَ فَخَلُّوا سَبِيلَهُمْ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ\"\n◇ممكن حد يسأل ويقول: طيب هو مش كده في تعارض بين آية السيف وبين آية 《لا إِكْرَاهَ فِي الدِّينِ》 \nالموضوع في قولين للعلماء:\n☆القول الأول بيقول:\nإن الآية دي والآيات إللي شبهها اتنسخت بآية السيف، يعني احنا بنقرأ آية لا إِكْرَاهَ فِي الدِّينِ عادي في القرآن لكن حكمها مبقاش موجود، \nفالمسلمين يعرضوا الإسلام على غير المسلمين، فاللي يرفض الإسلام نجاهده لحد ما يدخل في الإسلام،\nوده مفهوش ظلم يا جماعة بالعكس، ده فيه سعادتهم ونجاتهم في الدنيا والآخرة، \nهو لو واحد رافض ياخد علاج لمرض خطير، ولو مخدش العلاج ده هيموت مش بنلزمه إنه ياخده بالغصب\nفإلزام غير المسلمين بتوحيد الله والدخول في الإسلام أولى عشان الناس تنجوا من النار\nوالكلام ده لكل المشركين ما عدا اليهود والنصارى والمجوس،\nطيب ليه \n☆هو ده بقى القول للثاني للعلماء،\nقالوا:\nإن آية لا إِكْرَاهَ فِي الدِّينِ خاصة بالمجوس وأهل الكتاب من اليهود والنصارى ومن على شاكلتهم إذا أُعطوا الجزية للمسلمين، \nيعني لو اتعرض الإسلام على المجوس واليهود والنصارى ورفضوه، هنا يدفعوا الجزية ولا يُكرَهون على الدخول في الإسلام،\nودي الثلاث طوائف إللي يُؤخذ منها الجزية فقط،\nأي حد تاني غيرهم من الوثنيين وخصوصا عرب الجزيرة العربية لا يُؤخذ منه جزية؛ إما الإسلام وإما القتال،\nوده يوضح لنا ليه رسول الله ﷺ مكنش بياخد الجزية من مشركي العرب وكان بيقاتلهم مباشرة والقتال استمر معاهم بعد انقضاء العهد بينه وبينهم\n◇ملحوظة مهمة\nقتال المشركين إللي ربنا أمر بيه في آية السيف مرهون بقدرة المسلمين\nيعني الآية دي نزلت امتى؟\nمش نزلت لما كان المسلمين في عز قوتهم، وبقى لهم السيطرة الكاملة على جزيرة العرب حتى الروم ساعتها كانوا خايفين منهم ورفضوا إنهم يواجهوا المسلمين في غزوة تبوك\nمنزلتش الآية دي مثلا لما كان المسلمين مستضعفين في مكة، ولا نزلت حتى لما رسول الله ﷺ هاجر للمدينة وبقى للمسلمين بعض القوة،\nده معناه إن وقت ما يكون للمسلمين القوة والقدرة على قتال المشركين يجب عليهم إنهم يقاتلوهم زي ما ربنا أمر،\nطيب دلوقتي في زماننا المسلمين مستضعفين وبيُقتلوا في كل مكان،\nوالمسلمين نفسهم غارقانين في المعاصي والشهوات والمنكرات وفي منهم إللي بيحارب الدين،\nهنا بقى ينفع نطبق آية السيف\nطبعا لأ\nواجب الوقت دلوقتي هو تعبيد الناس لرب العالمين وتعليمهم دينهم الصحيح زي ما رسول الله ﷺ علّم الصحابة الدين في زمن الاستضعاف في مكة،\nولما يبقى للمسلمين القدرة والقوة والسيطرة زي ما حصل مع الصحابة في السنة التاسعة للهجرة هنا بقى يقاتلوا المشركين،\nحتى شيخ الإسلام ابن تيمية رحمه الله قال في كتاب الصارم المسلول:\n\"فمن كان من المؤمنين بأرض هو فيها مستضعف، أو في وقت هو فيه مستضعف: \nفليعمل بآية الصبر والصفح عمن يؤذي الله ورسوله من الذين أوتوا الكتاب والمشركين.\nوأما أهل القوة: \nفإنما يعملون بآية قتال أئمة الكفر الذين يطعنون في الدين، وبآية قتال الذين أوتوا الكتاب حتى يعطوا الجزية عن يد وهم صاغرون.\" \nيعني شيخ الإسلام ابن تيمية بيقول إن لو في وقت أو زمن المسلمين فيه مستضعفين يعملوا بآية الصبر والصفح وهي:\n\"قُلْ لِلَّذِينَ آمَنُوا يَغْفِرُوا لِلَّذِينَ لَا يَرْجُونَ أَيَّامَ اللَّهِ لِيَجْزِيَ قَوْمًا بِمَا كَانُوا يَكْسِبُونَ\"\nيعني ربنا بيأمر المؤمنين إنهم يتحملوا الأذى من المشركين ويصبروا على أذاهم وعلى أذى أهل الكتاب ويعرضوا عنهم ويغفروا لهم أذاهم ولا يردوا عليهم الأذى، وده كان في بداية الإسلام والمسلمين مستضعفين، \nلكن لما يكون للمسلمين قوة وقدرة فهنا بقى يقاتلوا أئمة الكفر وأتباعهم إللي بيطعنوا في الدين وبيؤذوا المسلمين\nمعلش يا جماعة جزء النهاردة مليان معلومات، يارب تكون الأمور واضحة"}]);
